type SharedOpeningTracker = Arc<Mutex<propagation::OpeningTracker>>;

/// Near-region opening spots (Phase 2): spots geographically near the operator on
/// the VHF/10 m opening bands where NEITHER end is the operator. Kept SEPARATE
/// from `SharedLivePaths` so they enrich the opening detector without polluting the
/// advisor's own-call "who hears me / who I hear".
///
/// A NEWTYPE, not a `type` alias: Tauri keys managed state by `TypeId`, and an
/// alias to `Arc<Mutex<LiveSpots>>` would collide with `SharedLivePaths` (same
/// TypeId) → `.manage()` panics at startup and DI can't tell the buffers apart.
#[derive(Clone)]
struct SharedRegionPaths(Arc<Mutex<propagation::LiveSpots>>);

/// Lifetime stop flag for the PSK Reporter MQTT daemon thread (see CLUSTER_STOP).
static PSKR_STOP: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);

/// One-shot latch for the PSK Reporter MQTT daemon thread (see RBN_CW_STARTED).
static PSKR_STARTED: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);
/// WSPR poller ownership: (generation, callsign being polled). A start for the
/// SAME call is a no-op (apply_settings calls this on every save); a start for
/// a DIFFERENT call — or an invalidated one — bumps the generation, which the
/// running thread observes and exits on (checked immediately before every
/// push, so even a fetch in flight across restart_live_feeds' drain can never
/// repollute the buffer with the old call's evidence — review catch).
static WSPR_FEED: Mutex<(u64, String)> = Mutex::new((0, String::new()));

/// One-shot latch for the near-region opening MQTT daemon thread (Phase 2).
static PSKR_REGION_STARTED: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Keep a near-region spot only if an end is within this many km of the operator.
/// 800 km — a station within ~strong-tropo / short-Es-hop range, i.e. "activity
/// genuinely touching my region". The old 2000 km ("one full Es hop") admitted
/// far↔far paths a continent away that polluted the operator-anchored opening
/// detector + advisor with activity the operator could NOT hear (the phantom-6m
/// complaint). The per-band global stream is gated client-side (the broker can't
/// filter by region).
const REGION_RADIUS_KM: f64 = 800.0;

/// Liveness of the background live feeds, updated from their daemon threads and
/// read by `get_feed_health` for the Now-Bar connector pills. Timestamps are Unix
/// secs of the last *successfully parsed* event; `0` = none yet this session.
#[derive(Default)]
struct FeedHealthState {
    /// Last parsed DX-cluster / RBN spot.
    cluster_last: std::sync::atomic::AtomicI64,
    /// Last successfully parsed PSK Reporter MQTT report.
    pskr_last_event: std::sync::atomic::AtomicI64,
    /// Cluster telnet session currently up (set on TCP-established, cleared on drop).
    /// Lets the pill say "connected" (quiet but healthy) instead of an ambiguous
    /// "waiting" that reads as broken.
    cluster_connected: std::sync::atomic::AtomicBool,
    /// PSK Reporter MQTT session currently up (set on accepted CONNACK, cleared on drop).
    pskr_connected: std::sync::atomic::AtomicBool,
    /// Last parsed PHONE-CLASSED spot from any human DX-cluster node — the true "is SSB
    /// actually arriving?" signal. Stamped ONLY when a human-node spot classifies as Phone
    /// (a human node's feed is mostly CW; stamping on every spot made the pill read live off
    /// CW traffic and masked a phone drought). Per-node connected state lives in
    /// [`PHONE_NODE_CONNS`].
    phone_cluster_last: std::sync::atomic::AtomicI64,
    /// Running count of PHONE-classed spots seen from human nodes this session — the
    /// diagnostic number behind "N SSB spots" on the Needed board. Reset on a feed restart.
    phone_spots_seen: std::sync::atomic::AtomicI64,
}
type SharedHealth = Arc<FeedHealthState>;

/// Cached QRZ XML session key (in-memory only — it's IP-bound, short-lived, and
/// re-derivable from the keychain password, so it never persists). `None` = not
/// logged in yet / expired.
type SharedQrzSession = Arc<Mutex<Option<String>>>;

/// Cached HamQTH XML session id (in-memory only — short-lived, re-derivable from
/// the keychain password, never persisted). `None` = not logged in yet / expired.
///
/// A NEWTYPE, not a bare alias like `SharedQrzSession`: a `type` alias of the same
/// `Arc<Mutex<Option<String>>>` shares QRZ's `TypeId`, so Tauri's TypeId-keyed
/// managed-state DI could not tell the two session caches apart (and `.manage()`
/// would collide). This is the same reason `SharedRegionPaths` is a newtype beside
/// `SharedLivePaths`.
#[derive(Default)]
struct SharedHamQthSession(Arc<Mutex<Option<String>>>);

/// A feed counts as "live" if it parsed an event within this window; older ⇒
/// "idle" (a lull on a quiet band, or a feed problem — the UI tooltip says so).
/// Generous so a normal band lull doesn't flip the pill.
const FEED_FRESH_SECS: i64 = 900;

/// PSK Reporter MQTT broker (plain MQTT over TCP).
const PSKR_MQTT_ADDR: &str = "mqtt.pskreporter.info:1883";

/// Current Unix time in seconds.
fn now_unix() -> i64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0)
}

/// How long ago a roster entry was actually decoded, in seconds — or `None` when
/// it cannot be aged, or is too stale to feed the propagation engine at all.
///
/// The roster stores a monotonic slot index rather than wall clock (so it stays
/// testable), and the active tier's T/R period converts it: 15 s on FT8, 7.5 s on
/// FT4, 4 s on FT1. `max_age_secs` is the caller's window; past it the entry is
/// dropped rather than aged, because [`tempo_core::roster::Roster`] never evicts on
/// its own — a band QSY's `clear()` is its only removal path — so this is the only
/// thing standing between an all-day roster and the opening detector.
///
/// **A slot index is only meaningful against the period it was numbered under.**
/// `slot = floor(now_ms / period_ms)` ([`tempo_core::timing`]), so the audio loop
/// RENUMBERS the clock the moment the tier's period changes, and the roster survives
/// that change (`Engine::set_tier` flushes the decode context, not the stations). An
/// entry carrying a pre-switch number is then being read against a clock it was never
/// on, and there is nothing in it to convert with — `HeardStation` carries the slot
/// alone, not the period it was taken at.
///
/// Both directions are therefore refused rather than aged, and the refusal is the
/// point: an un-ageable entry must never reach the detector as live evidence.
/// - period SHRANK (FT8 → FT4/FT1): the new `slot_now` runs far ahead of the old
///   numbering, the computed age is enormous, and `max_age_secs` drops it;
/// - period GREW (FT4/FT1 → FT8): the old number runs AHEAD of `slot_now`, which is
///   impossible on one clock — so it is refused here. This is what `saturating_sub`
///   alone could not do: it read those entries as age 0, i.e. as the freshest
///   evidence on the band, which is precisely the defect the real-decode-age fix
///   was written to remove.
///
/// A rig/clock re-sync that restarts the slot counter lands in that same
/// ahead-of-now branch and is likewise refused: on a live band the station is
/// re-decoded within a slot or two, which is a cheaper price than an hours-old
/// decode presented as current.
fn roster_spot_age_secs(
    slot_now: u64,
    last_heard_slot: u64,
    period_secs: f64,
    max_age_secs: i64,
) -> Option<i64> {
    if last_heard_slot > slot_now {
        return None;
    }
    let period = period_secs.max(1.0);
    let age = ((slot_now - last_heard_slot) as f64 * period).round() as i64;
    (age <= max_age_secs).then_some(age)
}

/// The operator's OWN decoded roster on the current band, as "I heard X" `PathSpot`s
/// carrying their REAL decode times.
///
/// Lifted out of [`get_propagation`] so a test can hold a roster and a slot clock and
/// read what the propagation engine is actually handed — the stamp is the whole
/// defect, and [`roster_spot_age_secs`] on its own cannot show whether the caller
/// applies it.
///
/// Every entry is stamped `t - age`, never `t`. The roster does not evict (a band
/// QSY's `clear()` is its only removal path), so stamping the poll time re-injected
/// the whole accumulated roster into the opening detector's most-recent bin on every
/// 30 s poll: that both fabricated the rate anomaly (nothing ever aged into the
/// baseline) and supplied hours-old DX as live evidence, which is how a dead 6 m band
/// alerted and stayed latched (operator 2026-08-05). Entries `roster_spot_age_secs`
/// refuses — older than the detector's own baseline window, or numbered under a
/// different slot clock — are dropped, not stamped with a guess.
#[allow(clippy::too_many_arguments)]
fn roster_local_spots(
    stations: &[tempo_app::dto::Station],
    slot_now: u64,
    period_secs: f64,
    band: propagation::model::Band,
    mycall: &str,
    me_grid: Option<String>,
    t: i64,
    max_age_secs: i64,
) -> Vec<propagation::PathSpot> {
    stations
        .iter()
        .filter_map(|st| {
            let age =
                roster_spot_age_secs(slot_now, st.last_heard_slot, period_secs, max_age_secs)?;
            Some(propagation::PathSpot {
                time: t - age,
                tx_call: st.call.to_uppercase(),
                tx_grid: st.grid.clone(),
                rx_call: mycall.to_uppercase(),
                rx_grid: me_grid.clone(),
                band,
                mode: None,
                snr: Some(st.snr as f32),
                freq_mhz: None, // own decodes are band-level here
            })
        })
        .collect()
}

/// The operator's OWN decodes on the current band as [`propagation::Heard`] rows —
/// the Needed board's strongest claim ("heard by MY radio, on this band, NOW").
///
/// FRESHNESS GATE (operator 2026-07-23, "decoded 11 minutes ago is too long"): the
/// roster never evicts — a station decoded once stays in `snap.stations` until a band
/// change clears it — so without an age cut a single decode feeds the board forever.
///
/// The age is [`roster_spot_age_secs`], the SAME conversion the opening detector's
/// [`roster_local_spots`] uses, because it is the same roster read against the same
/// slot clock. It was not, until 2026-08-05: this arm aged `last_heard_slot` with a
/// bare `saturating_sub`, which floors to 0 for an entry numbered under a LONGER T/R
/// period, i.e. reads an hours-old decode as this instant. Measured on the real
/// `SlotClock`: `VE3ABC` decoded on FT4 at 17:00 is slot 233,921,760; after a switch to
/// FT8 the 18:00 slot is 116,961,120. `Engine::set_tier` (`tempo-app/src/engine.rs`)
/// flushes the decode context but not the roster, so the hour-old entry — carrying a
/// number twice the size of "now" — led the board as the freshest evidence on the band.
/// The tier-switch fix landed on `roster_local_spots` and not here, ten thousand lines
/// away in this same file and one `last_heard_slot` grep apart.
///
/// Lifted out of [`get_need_alerts`] for the same reason `roster_local_spots` was:
/// `roster_spot_age_secs` on its own cannot show whether the caller applies it, and
/// this caller did not.
fn own_decode_heards(
    stations: &[tempo_app::dto::Station],
    slot_now: u64,
    period_secs: f64,
    band: &str,
    tier_mode: &str,
    max_age_secs: i64,
) -> Vec<propagation::Heard> {
    stations
        .iter()
        .filter(|s| {
            roster_spot_age_secs(slot_now, s.last_heard_slot, period_secs, max_age_secs).is_some()
        })
        .map(|s| propagation::Heard {
            call: s.call.clone(),
            band: band.to_string(),
            mode: tier_mode.to_string(),
            freq_mhz: None, // own decodes are band-level here
            admitted_at: None,
            evidence: Some("decoded by YOUR radio on this band".to_string()),
            grid: s.grid.clone(), // own decode's Maidenhead grid → drives NewGrid
            // US state hint (drives WAS NewState): FCC baseline refined by this live decode grid —
            // a precise 6-char grid that disagrees with the license means a rover. See us_state_hint.
            us_state: us_state_hint(&s.call, s.grid.as_deref()),
        })
        .collect()
}

/// A plausibly-real operator callsign — checked by SHAPE, not a denylist. Network
/// features that log in to public services (DX cluster / RBN, PSK Reporter MQTT)
/// gate on this so they never key an unset/garbage call on a public service.
///
/// The old check denylisted exactly `"KD9TAW"` (the shipped placeholder) — but
/// that is also a real operator's call, so it left every feed permanently OFF for
/// that operator. The default is now empty (`""`), and "configured" = a real call
/// has been entered (3–10 chars, has a letter AND a digit, alnum/`/` only).
fn is_real_call(call: &str) -> bool {
    let c = call.trim();
    let len = c.chars().count();
    (3..=10).contains(&len)
        && c.chars().any(|ch| ch.is_ascii_digit())
        && c.chars().any(|ch| ch.is_ascii_alphabetic())
        && c.chars().all(|ch| ch.is_ascii_alphanumeric() || ch == '/')
}

/// Connect ALL enabled spot sources (SpotCollector-style aggregation): the RBN CW + RBN
/// digital skimmer firehoses, plus EVERY human DX-cluster node in `cluster_hosts` — the
/// SSB/phone aggregator. RBN endpoints are wired once via fixed latches; the human nodes use
/// a per-host latch ([`HUMAN_NODES_STARTED`]) so a node added in Settings connects on the next
/// save with no restart, and an RBN endpoint that sneaks into the list is skipped (no
/// double-connect). No-op per feed unless `mycall` is a [`is_real_call`]; the caller owns the
/// `Settings::cluster_active` gate (which folds in Unassisted mode). All push into the one
/// shared `spots` buffer the need-matcher reads.
fn start_cluster_feeds(
    spots: &SharedSpots,
    cluster_hosts: &[String],
    mycall: &str,
    health: &SharedHealth,
) {
    start_cluster_feed(spots, RBN_CW_HOST, mycall, health, &RBN_CW_STARTED);
    start_cluster_feed(
        spots,
        RBN_DIGITAL_HOST,
        mycall,
        health,
        &RBN_DIGITAL_STARTED,
    );
    for host in cluster_hosts {
        let h = host.trim();
        if h.is_empty() || h.contains("reversebeacon.net") {
            continue; // blank, or an RBN endpoint already wired above
        }
        start_human_cluster_feed(spots, h, mycall, health);
    }
}

/// Spawn one RBN skimmer telnet feed (CW or digital). Once-latched via `started`; each parsed
/// spot stamps the aggregate `cluster_last` and the session toggles `cluster_connected`.
fn start_cluster_feed(
    spots: &SharedSpots,
    cluster_host: &str,
    mycall: &str,
    health: &SharedHealth,
    started: &std::sync::atomic::AtomicBool,
) {
    if !is_real_call(mycall) || started.swap(true, std::sync::atomic::Ordering::SeqCst) {
        return;
    }
    conn_log(
        "RBN",
        "info",
        format!(
            "connecting to {} as {}",
            cluster_host,
            mycall.trim().to_uppercase()
        ),
    );
    let buf = spots.clone();
    let hp = health.clone();
    let hp_conn = health.clone();
    let host = cluster_host.to_string();
    let call = mycall.trim().to_string();
    std::thread::spawn(move || {
        tempo_net::cluster::run(
            &host,
            &call,
            |sp| {
                // UNASSISTED mode: drop the spot at the door, before the health stamp, the
                // buffer and Pounce. Checked here rather than only at the start gate so a
                // mid-event flip takes effect on the very next packet without waiting for a
                // socket teardown. The feed intentionally stays connected and simply
                // discards — reconnecting later is what would cost the operator spots.
                if unassisted() {
                    return;
                }
                hp.cluster_last
                    .store(now_unix(), std::sync::atomic::Ordering::Relaxed);
                if let Ok(mut b) = buf.lock() {
                    // Mark the skimmer origin so a leading "RTTY" comment token can
                    // UPGRADE the display label (is_rbn_rtty) — trusted only here, on
                    // the machine-generated RBN wire, never on the human-node path.
                    let mut s = sp.clone();
                    s.rbn = true;
                    pounce_offer(&s);
                    // RANKED, never plain `push`: the buffer's corroborator cap has to
                    // choose which voices a re-spotted row keeps, and the Needed board
                    // admits the row on whether a NEAR voice is among them.
                    b.push_ranked(s, spotter_evidence_rank);
                }
            },
            &CLUSTER_STOP,
            &hp_conn.cluster_connected,
            &RBN_DEAD_OUTBOX, // RBN is receive-only — never post to a skimmer
        );
    });
}

// ---------------------------------------------------------------------------------------------
// APRS-IS — the internet inlet for APRS, and the receive-only iGate
// ---------------------------------------------------------------------------------------------

/// The running APRS-IS feed, if any. One feed per process, unlike the multi-node cluster
/// aggregator: APRS-IS is a single logical network and a second login would be a duplicate.
struct AprsIsFeed {
    /// Everything a change of which forces a reconnect — the server, and the login line (which
    /// carries the callsign, the passcode, and the whole server-side filter).
    fingerprint: String,
    /// Set to stop both this feed's threads. They own `Arc`s to the state and outbox, so nothing
    /// else needs to be held here to keep them alive.
    stop: Arc<std::sync::atomic::AtomicBool>,
}

static APRS_IS_FEED: Mutex<Option<AprsIsFeed>> = Mutex::new(None);

/// Reconcile the APRS-IS feed with settings: start it, stop it, or reconnect it under a changed
/// server/filter/callsign. Called at startup and after every Save, so a filter edit takes effect
/// without a restart.
///
/// ⚠️ **Deliberately independent of the APRS RF decoder's arm state.** See the doc comment on
/// `Settings::aprs_is_enabled` for why: the feed costs no RF resource, can key nothing, and its
/// value as a diagnostic depends on it running while the RF side is silent.
fn sync_aprs_is_feed(engine: &SharedEngine) {
    let (want, login, addr) = {
        let eng = engine_lock(engine);
        let s = eng.settings();
        let call = s.mycall.trim().to_string();
        // A real callsign is required even read-only: it is the login identity on a public
        // amateur service, and `pass -1` still names us to every server on the network.
        let want = s.aprs_is_enabled && is_real_call(&call);
        // The uplink additionally needs the passcode, which is derived from that same callsign.
        let code = s
            .aprs_is_uplink
            .then(|| tempo_core::aprs::is::passcode(&call));
        let filter = tempo_core::aprs::is::FilterSpec {
            range_km: Some(s.aprs_is_radius_km),
            center: propagation::geo::maidenhead_to_latlon(s.mygrid.trim()),
            buddies: s.aprs_is_watch_calls.clone(),
            weather: s.aprs_is_weather,
            objects: s.aprs_is_objects,
            messages: s.aprs_is_messages,
        }
        .build();
        let login = tempo_core::aprs::is::login_line(
            &call,
            code,
            "Nexus",
            env!("CARGO_PKG_VERSION"),
            &filter,
        );
        let host = s.aprs_is_host.trim();
        let host = if host.is_empty() {
            "rotate.aprs2.net"
        } else {
            host
        };
        (want, login, format!("{host}:{}", s.aprs_is_port))
    };

    let fingerprint = format!("{addr}\u{1}{login}");
    let mut slot = APRS_IS_FEED.lock().unwrap_or_else(|e| e.into_inner());
    if let Some(f) = slot.as_ref() {
        if want && f.fingerprint == fingerprint {
            return; // already running exactly this
        }
        // Server, filter, callsign or uplink changed — the login line carries all of them, so the
        // only way to apply it is a fresh session.
        f.stop.store(true, std::sync::atomic::Ordering::SeqCst);
        *slot = None;
    }
    if !want {
        {
            let mut eng = engine_lock(&engine);
            eng.set_aprs_is_status(Default::default());
        }
        return;
    }

    conn_log("APRS-IS", "info", format!("connecting to {addr}"));
    let stop = Arc::new(std::sync::atomic::AtomicBool::new(false));
    let state = Arc::new(tempo_net::aprsis::FeedState::default());
    let outbox = Arc::new(Mutex::new(std::collections::VecDeque::new()));
    *slot = Some(AprsIsFeed {
        fingerprint,
        stop: stop.clone(),
    });
    drop(slot);

    // The socket thread: receive lines, decode them, push them into the SAME store the RF decoder
    // writes — tagged `Inet` so nothing downstream has to guess where a station came from.
    {
        let eng = engine.clone();
        let (stop, state, outbox) = (stop.clone(), state.clone(), outbox.clone());
        std::thread::Builder::new()
            .name("aprs-is".into())
            .spawn(move || {
                tempo_net::aprsis::run(
                    &addr,
                    &login,
                    |line| {
                        let Some(pkt) = tempo_core::aprs::AprsPacket::from_tnc2(line) else {
                            return;
                        };
                        {
                            let mut e = engine_lock(&eng);
                            e.push_aprs_heard(tempo_app::engine::AprsHeard::from_packet(
                                &pkt,
                                now_unix(),
                                tempo_app::engine::AprsSource::Inet,
                                String::from_utf8_lossy(line).into_owned(),
                            ));
                        }
                    },
                    &stop,
                    &state,
                    &outbox,
                );
            })
            .expect("spawn aprs-is");
    }

    // The bridge thread: mirrors feed state into the engine for the status chip, and carries
    // RF-heard packets the other way. Separate from the socket thread on purpose — the uplink
    // must keep flowing on a quiet feed, and it must never run inside a socket callback.
    {
        let eng = engine.clone();
        std::thread::Builder::new()
            .name("aprs-is-gate".into())
            .spawn(move || aprs_is_bridge(eng, stop, state, outbox))
            .expect("spawn aprs-is-gate");
    }
}

/// Carry packets between the engine and the APRS-IS socket once per second: publish the feed's
/// live state for the status chip, and gate RF-heard packets into the upload queue.
///
/// **This is where the iGate's published behaviour is decided.** Every packet passes, in order:
/// the RF-only rule (enforced upstream — only `AprsSource::Rf` pushes queue at all), the path
/// guards, the duplicate window, then the rate cap. A packet failing any of them is counted and
/// dropped, never sent.
fn aprs_is_bridge(
    engine: SharedEngine,
    stop: Arc<std::sync::atomic::AtomicBool>,
    state: Arc<tempo_net::aprsis::FeedState>,
    outbox: Arc<Mutex<std::collections::VecDeque<Vec<u8>>>>,
) {
    use std::sync::atomic::Ordering;
    let mut dupes = tempo_core::aprs::is::DupeWindow::default();
    let mut rate = tempo_core::aprs::is::RateCap::default();
    let mut rejected: u64 = 0;
    let mut last_reject: Option<String> = None;
    while !stop.load(Ordering::SeqCst) {
        std::thread::sleep(std::time::Duration::from_secs(1));
        let (queued, igate_call, uplink_on) = {
            let mut e = engine_lock(&engine);
            let call = e.settings().mycall.trim().to_string();
            let on = e.settings().aprs_is_uplink;
            (e.take_aprs_uplink(), call, on)
        };
        let now = now_unix();
        let mut to_send: Vec<Vec<u8>> = Vec::new();
        // Only a VERIFIED login may upload; without one the server refuses us anyway, and gating
        // work on packets that can never be sent is pointless.
        if uplink_on && state.verified.load(Ordering::Relaxed) {
            for line in queued {
                let bytes = line.as_bytes();
                if let Err(why) = tempo_core::aprs::is::gate_check(bytes) {
                    rejected += 1;
                    last_reject = Some(why.reason());
                    continue;
                }
                if !dupes.accept(bytes, now) {
                    rejected += 1;
                    last_reject = Some("duplicate".into());
                    continue;
                }
                if !rate.accept(now) {
                    rejected += 1;
                    last_reject = Some("rate cap".into());
                    continue;
                }
                if let Some(gated) = tempo_core::aprs::is::gated_line(bytes, &igate_call) {
                    to_send.push(gated);
                }
            }
        }
        if !to_send.is_empty() {
            if let Ok(mut q) = outbox.lock() {
                q.extend(to_send);
            }
        }
        let last_packet = state.last_packet_unix.load(Ordering::Relaxed);
        {
            let mut e = engine_lock(&engine);
            e.set_aprs_is_status(tempo_app::engine::AprsIsStatus {
                // `enabled` / `uplink_enabled` are re-derived from settings by the getter.
                connected: state.connected.load(Ordering::Relaxed),
                verified: state.verified.load(Ordering::Relaxed),
                packets: state.packets.load(Ordering::Relaxed),
                last_packet_unix: (last_packet > 0).then_some(last_packet),
                uploaded: state.uploaded.load(Ordering::Relaxed),
                gate_rejected: rejected,
                last_reject: last_reject.clone(),
                ..Default::default()
            });
        }
    }
}

/// Spawn ONE human DX-cluster node feed (an SSB/phone source). Per-host once-latch via
/// [`HUMAN_NODES_STARTED`] (so re-running the aggregator only spawns nodes not already up).
/// Each parsed spot stamps BOTH the aggregate `cluster_last` AND `phone_cluster_last`, and the
/// session toggles this node's own connected flag (registered in [`PHONE_NODE_CONNS`]) so the
/// phone-source pill reflects "any node up" — readable independently of the busy RBN feeds.
fn start_human_cluster_feed(spots: &SharedSpots, host: &str, mycall: &str, health: &SharedHealth) {
    if !is_real_call(mycall) {
        return;
    }
    {
        let mut started = match HUMAN_NODES_STARTED.lock() {
            Ok(g) => g,
            Err(_) => return,
        };
        if started.iter().any(|h| h.eq_ignore_ascii_case(host)) {
            return; // this node is already connected this session (case-insensitive)
        }
        started.push(host.to_string());
    }
    conn_log(
        "DX Cluster",
        "info",
        format!("connecting to {} as {}", host, mycall.trim().to_uppercase()),
    );
    let conn = Arc::new(std::sync::atomic::AtomicBool::new(false));
    if let Ok(mut v) = PHONE_NODE_CONNS.lock() {
        v.push(conn.clone());
    }
    let buf = spots.clone();
    let hp = health.clone();
    let host = host.to_string();
    let call = mycall.trim().to_string();
    std::thread::spawn(move || {
        tempo_net::cluster::run(
            &host,
            &call,
            |sp| {
                // UNASSISTED mode: drop at the door — see the RBN callback above.
                if unassisted() {
                    return;
                }
                let ts = now_unix();
                hp.cluster_last
                    .store(ts, std::sync::atomic::Ordering::Relaxed);
                // Only a PHONE-classed spot proves SSB is actually reaching us — a human
                // node's feed is mostly CW (RBN relay + human CW), which would otherwise keep
                // the Phone pill green and hide a phone drought. Classify the same way the
                // need-matcher does.
                if matches!(
                    propagation::classify_spot_mode(sp.freq_mhz()),
                    propagation::ModeClass::Phone
                ) {
                    hp.phone_cluster_last
                        .store(ts, std::sync::atomic::Ordering::Relaxed);
                    hp.phone_spots_seen
                        .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                }
                if let Ok(mut b) = buf.lock() {
                    pounce_offer(sp);
                    // Ranked — see the RBN callback above.
                    b.push_ranked(sp.clone(), spotter_evidence_rank);
                }
            },
            &CLUSTER_STOP,
            &conn,
            &CLUSTER_OUTBOX, // the post target — `post_spot` pushes DX lines here
        );
    });
}

/// Spawn the PSK Reporter MQTT firehose thread once per process (the [`PSKR_STARTED`]
/// latch makes repeat calls a no-op). No-op unless `mycall` is a [`is_real_call`].
/// Parsed live `PathSpot`s flow into `live_paths`, which `get_propagation` merges
/// into the nowcast; each parsed report stamps `health.pskr_last_event` (so a
/// connected-but-all-drops feed shows "waiting", not "live"). The CAS latch
/// guarantees no double-spawn across concurrent `set_settings` calls and startup.
fn start_pskr_feed(live_paths: &SharedLivePaths, mycall: &str, health: &SharedHealth) {
    if !is_real_call(mycall) || PSKR_STARTED.swap(true, std::sync::atomic::Ordering::SeqCst) {
        return;
    }
    conn_log(
        "PSKR MQTT",
        "info",
        format!("subscribing for {}", mycall.trim().to_uppercase()),
    );
    let buf = live_paths.clone();
    let hp = health.clone();
    let hp_conn = health.clone();
    let call = mycall.trim().to_string();
    std::thread::spawn(move || {
        let topics = propagation::pskr_mqtt_topics(&call);
        let topic_refs: Vec<&str> = topics.iter().map(|s| s.as_str()).collect();
        tempo_net::mqtt::subscribe(
            PSKR_MQTT_ADDR,
            &format!("nexus-{call}"),
            &topic_refs,
            |topic, payload| {
                if let Some(spot) = propagation::parse_pskr_mqtt_payload(topic, payload, now_unix())
                {
                    hp.pskr_last_event
                        .store(now_unix(), std::sync::atomic::Ordering::Relaxed);
                    // Rarity census: every heard TX grid is activity evidence.
                    if let Some(g) = spot.tx_grid.as_deref() {
                        if let Ok(mut c) = propagation::gridrarity::census().write() {
                            c.observe(g);
                        }
                    }
                    if let Ok(mut b) = buf.lock() {
                        b.push(spot);
                    }
                }
            },
            &PSKR_STOP,
            &hp_conn.pskr_connected,
        );
    });
}

/// Poll wspr.live every 5 min for who's hearing MYCALL's WSPR beacons — the
/// beacon-grade "getting out" evidence lane (bounded 1-hour query per the
/// wspr.live fair-use policy; data courtesy of wspr.live / wsprnet.org). Rows
/// at-or-before the newest already-pushed timestamp are skipped, so re-fetching
/// the sliding window never duplicates bus entries. Best-effort: a WSPR-less
/// station simply gets empty answers. Each call OWNS a new WSPR_GEN generation:
/// the previous poller (if any) exits at its next check, so a callsign change
/// tears the old-call query down instead of leaving it repolluting the drained
/// buffer (review catch).
fn start_wspr_feed(live_paths: &SharedLivePaths, mycall: &str) {
    let call_ok = is_real_call(mycall);
    let call = mycall.trim().to_uppercase();
    let my_gen = {
        let Ok(mut g) = WSPR_FEED.lock() else { return };
        if call_ok && g.1 == call {
            return; // already polling this exact call — idempotent
        }
        // Supersede whatever ran before (a rename kills the old-call poller
        // even when the new call is invalid — feeds stay down, honestly).
        g.0 += 1;
        g.1 = if call_ok { call.clone() } else { String::new() };
        if !call_ok {
            return;
        }
        g.0
    };
    let alive = move || WSPR_FEED.lock().map(|g| g.0 == my_gen).unwrap_or(false);
    let buf = live_paths.clone();
    std::thread::spawn(move || {
        let mut newest = 0i64;
        loop {
            if !alive() {
                return; // superseded (rename/restart) — die quietly
            }
            if let Ok(spots) = propagation::live::wspr::fetch_wspr(&call) {
                // Re-check AFTER the (up to 20 s) fetch so an in-flight answer
                // for the OLD call can never land after the rename drain.
                if !alive() {
                    return;
                }
                let fresh: Vec<_> = spots.into_iter().filter(|s| s.time > newest).collect();
                if let Some(m) = fresh.iter().map(|s| s.time).max() {
                    newest = m;
                }
                if !fresh.is_empty() {
                    if let Ok(mut b) = buf.lock() {
                        for sp in fresh {
                            b.push(sp);
                        }
                    }
                }
            }
            // 5-min cadence, sliced so a superseded poller exits within ~2 s.
            for _ in 0..150 {
                if !alive() {
                    return;
                }
                std::thread::sleep(std::time::Duration::from_secs(2));
            }
        }
    });
}

/// Spawn the near-region opening MQTT thread once per process (Phase 2). No-op
/// unless `mycall` is real, `mygrid` resolves (nothing can be "near" otherwise),
/// and the operator hasn't opted out. Subscribes to the per-band VHF/10 m global
/// streams, then keeps only spots that are (a) NOT the operator's own paths (those
/// live in `live_paths`) and (b) within `REGION_RADIUS_KM` of the operator — so the
/// opening detector can flag "a band is open around you" while the buffers stay
/// disjoint and field-rig-bounded. Time-evicts on push so a wide opening can't
/// truncate the baseline.
fn start_pskr_region_feed(region_paths: &SharedRegionPaths, mycall: &str, mygrid: &str) {
    if !is_real_call(mycall)
        || propagation::geo::maidenhead_to_latlon(mygrid).is_none()
        || PSKR_REGION_STARTED.swap(true, std::sync::atomic::Ordering::SeqCst)
    {
        return;
    }
    let buf = region_paths.0.clone();
    let call = mycall.trim().to_string();
    let grid = mygrid.trim().to_string();
    std::thread::spawn(move || {
        // VHF/10m: global per-band streams (self-throttling). HF F2: the
        // grid-targeted census — server-side filtered to the operator's region
        // so the broker never sends the global 20m firehose.
        let mut topics = propagation::pskr_region_topics();
        topics.extend(propagation::hf_region_topics(&grid, REGION_RADIUS_KM));
        let topic_refs: Vec<&str> = topics.iter().map(|s| s.as_str()).collect();
        let base_w = propagation::OpeningConfig::default().base_w;
        // No Now-Bar pill for the region feed — session state isn't surfaced.
        let connected = std::sync::atomic::AtomicBool::new(false);
        tempo_net::mqtt::subscribe(
            PSKR_MQTT_ADDR,
            &format!("nexus-rgn-{call}"),
            &topic_refs,
            |topic, payload| {
                let now = now_unix();
                let Some(spot) = propagation::parse_pskr_mqtt_payload(topic, payload, now) else {
                    return;
                };
                // Own-call paths belong to live_paths; keep only far↔far so the
                // two buffers are disjoint (no double-count in the anomaly rate).
                if spot.side(&call) != propagation::Side::Neither {
                    return;
                }
                // Near-region gate, failing CLOSED: at least one end within radius.
                let near = [spot.tx_grid.as_deref(), spot.rx_grid.as_deref()]
                    .into_iter()
                    .flatten()
                    .any(|g| {
                        propagation::geo::grid_distance_km(&grid, g)
                            .is_some_and(|d| d <= REGION_RADIUS_KM)
                    });
                if !near {
                    return;
                }
                if let Some(g) = spot.tx_grid.as_deref() {
                    if let Ok(mut c) = propagation::gridrarity::census().write() {
                        c.observe(g);
                    }
                }
                if let Ok(mut b) = buf.lock() {
                    b.push(spot);
                    b.trim_older_than(now - (base_w + 600));
                }
            },
            &PSKR_STOP,
            &connected,
        );
    });
}

/// Per-feed liveness for the Now-Bar connector pills.
#[derive(serde::Serialize)]
#[serde(rename_all = "camelCase")]
struct FeedStatus {
    /// The feed's daemon thread is running. It is started once a real callsign
    /// (and, for the cluster, its toggle) is set, and then runs until app exit —
    /// so this can stay true after the cluster toggle is later turned off (the
    /// connection genuinely persists until restart). When false the UI hides the pill.
    enabled: bool,
    /// Seconds since the last parsed spot/report; `null` if none yet this session.
    last_event_secs: Option<i64>,
    /// "off" | "connecting" | "connected" | "live" | "idle" | "reconnecting"
    /// (only meaningful when `enabled`). "connected" = session up but no event parsed
    /// yet (normal on a quiet band — NOT broken); "connecting" = thread running, no
    /// session yet; "reconnecting" = had events, session currently down.
    state: String,
}

/// Liveness of the background live feeds.
#[derive(serde::Serialize)]
#[serde(rename_all = "camelCase")]
struct FeedHealth {
    cluster: FeedStatus,
    pskr: FeedStatus,
    /// The HUMAN DX-cluster nodes as a group — the SSB/phone source, reported separately from
    /// the aggregate `cluster` pill (which the RBN CW/digital firehose keeps green on its own).
    /// `connected` = ANY node up; `enabled: false` when no human node is configured (RBN-only).
    phone_cluster: FeedStatus,
    /// Compact phone-source label: the host for one node, "host +N" for several, `None` for
    /// none (RBN-only operator).
    phone_cluster_host: Option<String>,
    /// Count of PHONE-classed spots received from human nodes this session — lets the Needed
    /// board show "N SSB spots", splitting "SSB isn't arriving" (0) from "arriving but not a
    /// need" (>0 with no phone rows).
    phone_spots_seen: i64,
}

fn feed_status(started: bool, connected: bool, last: i64, now: i64) -> FeedStatus {
    if !started {
        return FeedStatus {
            enabled: false,
            last_event_secs: None,
            state: "off".into(),
        };
    }
    if last == 0 {
        // No event parsed yet — the connected flag is what separates "healthy but
        // quiet" (normal: nobody has spotted the operator yet) from "can't reach the
        // server". Without it this read as a permanent, broken-looking "waiting".
        return FeedStatus {
            enabled: true,
            last_event_secs: None,
            state: if connected { "connected" } else { "connecting" }.into(),
        };
    }
    let age = (now - last).max(0);
    FeedStatus {
        enabled: true,
        last_event_secs: Some(age),
        state: if !connected {
            "reconnecting"
        } else if age <= FEED_FRESH_SECS {
            "live"
        } else {
            "idle"
        }
        .into(),
    }
}

/// Compact phone-source label for N connected human nodes: `None` for none, the bare host
/// for one, and "host +N" for several — enough for the Now-Bar pill / Needed-board line.
fn summarize_hosts(hosts: &[String]) -> Option<String> {
    match hosts.len() {
        0 => None,
        1 => Some(hosts[0].clone()),
        n => Some(format!("{} +{}", hosts[0], n - 1)),
    }
}

/// Liveness of the background live feeds, for the Now-Bar connector pills. A feed
/// is "live" if it parsed an event within FEED_FRESH_SECS, "waiting" if started
/// but silent so far, "idle" if it has gone quiet (a lull on a quiet band, or a
/// feed problem — the UI tooltip says so). Disabled feeds are hidden by the UI.
#[tauri::command]
fn get_feed_health(health: State<'_, SharedHealth>) -> FeedHealth {
    use std::sync::atomic::Ordering::Relaxed;
    let now = now_unix();
    // The human DX-cluster nodes (the SSB/phone aggregator): the spawned host list drives the
    // started flag + label, and "connected" = ANY node's session up.
    let human_hosts: Vec<String> = HUMAN_NODES_STARTED
        .lock()
        .map(|g| g.clone())
        .unwrap_or_default();
    let phone_connected = PHONE_NODE_CONNS
        .lock()
        .map(|v| v.iter().any(|b| b.load(Relaxed)))
        .unwrap_or(false);
    FeedHealth {
        cluster: feed_status(
            // Any of the cluster sources spawned (RBN CW/digital firehoses + any human node).
            RBN_CW_STARTED.load(Relaxed)
                || RBN_DIGITAL_STARTED.load(Relaxed)
                || !human_hosts.is_empty(),
            health.cluster_connected.load(Relaxed),
            health.cluster_last.load(Relaxed),
            now,
        ),
        pskr: feed_status(
            PSKR_STARTED.load(Relaxed),
            health.pskr_connected.load(Relaxed),
            health.pskr_last_event.load(Relaxed),
            now,
        ),
        // The human nodes as a group — their own started/connected/last, so a down SSB
        // source is visible even while RBN keeps the aggregate `cluster` pill green.
        phone_cluster: feed_status(
            !human_hosts.is_empty(),
            phone_connected,
            health.phone_cluster_last.load(Relaxed),
            now,
        ),
        phone_cluster_host: summarize_hosts(&human_hosts),
        phone_spots_seen: health.phone_spots_seen.load(Relaxed),
    }
}

/// How long a live propagation nowcast is reused before refetching (seconds).
const PROP_TTL_SECS: u64 = 300;

/// When the last live-propagation refetch was ATTEMPTED (success or failure).
/// Rate-limits refetches to one per [`PROP_TTL_SECS`] independent of the UI poll
/// cadence, so a failing fetch on a cold cache can't storm PSK Reporter into 429s.
static PROP_FETCH_BACKOFF: Mutex<Option<std::time::Instant>> = Mutex::new(None);

/// Last-good real-time solar wind (Bz/speed/…) — refreshed on each fresh SWPC-cadence poll
/// and reused on cache hits, so the leading-indicator insight survives between refetches.
/// `None` until the first successful fetch (SolarWind is Copy, so reads are cheap clones).
static LAST_SOLAR_WIND: Mutex<Option<propagation::SolarWind>> = Mutex::new(None);

/// Last-good 12-month smoothed sunspot number (R12) from SWPC's predicted
/// solar cycle — the p533 engine's proper solar input (daily SFI is the wrong
/// quantity for monthly-median CCIR maps; without this the engine falls back
/// to a Covington inversion of SFI). Refreshed on the space-wx fetch cadence.
static LAST_SSN: Mutex<Option<f32>> = Mutex::new(None);

/// The X-ray "fast lane" cache: (fetched-at, flux W/m², reading unix time). A
/// flare's rise takes minutes, so `get_xray_now` refetches GOES every 60 s —
/// much fresher than the 5-min snapshot TTL — and serves last-good on failure.
static LAST_XRAY: Mutex<Option<(std::time::Instant, f32, i64)>> = Mutex::new(None);

/// The base config root: `%APPDATA%` on Windows, `$XDG_CONFIG_HOME`/`~/.config` on Unix,
/// else the CWD. The `tempo[-<profile>]` app directory hangs off this.
fn config_base() -> PathBuf {
    let base = if cfg!(windows) {
        std::env::var_os("APPDATA").map(PathBuf::from)
    } else {
        std::env::var_os("XDG_CONFIG_HOME")
            .map(PathBuf::from)
            .or_else(|| std::env::var_os("HOME").map(|h| PathBuf::from(h).join(".config")))
    };
    base.unwrap_or_else(|| PathBuf::from("."))
}

/// Accept only a filesystem-safe profile name — `[A-Za-z0-9_-]`, 1..=32 chars. Anything
/// else (empty, path separators, junk) → `None` = the default profile, so a bad value can
/// never escape the config root or silently split the config into a garbage directory.
fn sanitize_profile(s: &str) -> Option<String> {
    let t = s.trim();
    let ok = !t.is_empty()
        && t.len() <= 32
        && t.bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'-' || b == b'_');
    ok.then(|| t.to_string())
}

/// The active instance profile, resolved once: `--profile <name>` (or `--profile=<name>`) on
/// the command line wins, else the `NEXUS_PROFILE` env var. `None` = the DEFAULT profile,
/// whose config dir is plain `tempo` — byte-identical to the pre-profile layout, so a single
/// instance is unaffected. Two instances get separate config by launching with distinct
/// profiles; that is what keeps them from clobbering each other's settings/journals.
fn active_profile() -> Option<&'static str> {
    static PROFILE: OnceLock<Option<String>> = OnceLock::new();
    PROFILE
        .get_or_init(|| {
            let from_arg = {
                let mut found = None;
                let mut args = std::env::args().skip(1);
                while let Some(a) = args.next() {
                    if a == "--profile" {
                        found = args.next();
                        break;
                    } else if let Some(v) = a.strip_prefix("--profile=") {
                        found = Some(v.to_string());
                        break;
                    }
                }
                found
            };
            from_arg
                .or_else(|| std::env::var("NEXUS_PROFILE").ok())
                .and_then(|s| sanitize_profile(&s))
        })
        .as_deref()
}

/// The app-directory name for a profile: `tempo` (default) or `tempo-<profile>`. Pure, so the
/// naming is testable without touching env/args.
fn profile_dir_name(profile: Option<&str>) -> String {
    match profile {
        Some(p) => format!("tempo-{p}"),
        None => "tempo".to_string(),
    }
}

/// The config directory for a GIVEN profile (`None` = default) — `<base>/tempo[-<profile>]`.
/// Used to peek at another profile's lock without being that profile.
fn config_dir_for(profile: Option<&str>) -> PathBuf {
    config_base().join(profile_dir_name(profile))
}

/// The per-instance config directory for THIS instance's active profile: `<base>/tempo` for
/// the default, or `<base>/tempo-<profile>` for a named one. Holds settings.json + the journals
/// beside it (window geometry, Field Day, pending-QSO/msgs queues) — all correctly per-instance,
/// since each of those derives from [`settings_path`]'s parent.
fn config_dir() -> PathBuf {
    config_dir_for(active_profile())
}

/// The config-dir profile name that a radio drives, keyed on its STABLE `RadioProfile::id`
/// (`"r0"`, `"r1"`, …) so renaming a radio never orphans its window's config/journals.
///
/// KNOWN LIMITATION (pre-existing; recorded during the 2026-08 Doppler-consent audit, out of
/// its scope): the roster one level up REUSES freed ids — `Settings::add_radio_profile`
/// allocates `max+1`, so removing the highest-id radio and adding another hands the newcomer
/// the departed radio's id, and with it this `tempo-r<id>/` config dir: settings, window
/// geometry and journals included. The engine-side uplink consent prunes on remove for exactly
/// this reason; the per-radio config dirs do not. Also noted in CHANGELOG ▸ Known limitations.
fn radio_profile_key(radio_id: u32) -> String {
    format!("r{radio_id}")
}

/// The radio id THIS instance was launched to drive — `--profile r<id>`, as the launch picker
/// spawns it. `None` for the default profile and for a hand-named profile (`--profile hf`), which is
/// a deliberately independent station config: the fleet-level roster/routing mirroring below applies
/// only to the picker's radio windows.
fn bound_radio_id() -> Option<u32> {
    active_profile()
        .and_then(|p| p.strip_prefix('r'))
        .and_then(|s| s.parse::<u32>().ok())
}

/// Is another running instance already holding `profile`'s config dir? Checked via a std
/// advisory file lock: an instance holds an exclusive lock on `<config_dir>/.lock` for its whole
/// life ([`hold_profile_lock`]), so a `try_lock` that WOULD BLOCK means that radio's window is
/// already open. A missing dir / lock-unsupported filesystem reads as "free" (fail-open — the
/// picker just won't grey it out; the real guard is the holder's exclusive lock).
fn profile_in_use(profile: &str) -> bool {
    use std::fs::File;
    let lock = config_dir_for(Some(profile)).join(".lock");
    let Ok(f) = File::open(&lock) else {
        return false; // no lock file yet → never launched → free
    };
    match f.try_lock() {
        Ok(()) => {
            let _ = f.unlock(); // we only peeked — release immediately
            false
        }
        Err(std::fs::TryLockError::WouldBlock) => true, // someone holds it → in use
        Err(_) => false,                                // unsupported → fail-open
    }
}

/// Take THIS instance's advisory lock on its active profile's config dir and hold it for the
/// whole process lifetime (the `File` is leaked so it never drops/unlocks early). Returns false
/// if the SAME profile is already open in another window — the footgun guard: two instances of
/// one profile would clobber each other's per-instance journals. The default profile is never
/// locked (a lone single-radio instance needs no guard and must stay zero-overhead).
fn hold_profile_lock() -> bool {
    use std::fs::File;
    let Some(_p) = active_profile() else {
        return true; // default profile: no guard needed
    };
    let dir = config_dir();
    let _ = std::fs::create_dir_all(&dir);
    let Ok(f) = File::create(dir.join(".lock")) else {
        return true; // can't make a lock → fail-open rather than refuse to launch
    };
    match f.try_lock() {
        Ok(()) => {
            Box::leak(Box::new(f)); // hold for process lifetime
            true
        }
        Err(_) => false, // same profile already running
    }
}

/// One selectable radio in the launch picker.
#[derive(serde::Serialize)]
#[serde(rename_all = "camelCase")]
struct RadioLaunchOption {
    id: u32,
    name: String,
    /// Already open in another window (its profile lock is held) — the picker greys it out.
    in_use: bool,
}

/// What the frontend needs to decide whether to show the "which radio?" launch picker.
#[derive(serde::Serialize)]
#[serde(rename_all = "camelCase")]
struct RadioLaunchInfo {
    /// Show the picker: simultaneous-radios is enabled, ≥2 radios are configured, and THIS window
    /// launched without a profile (a fresh chooser launch, not an already-bound relaunch).
    show_picker: bool,
    radios: Vec<RadioLaunchOption>,
}

/// Tell the frontend whether to show the launch picker, and the radios to offer. Single-radio
/// stations (or multi-radio-off) get `show_picker=false` → the UI proceeds straight to operating.
#[tauri::command(async)]
fn radio_launch_info(state: State<'_, SharedEngine>) -> Result<RadioLaunchInfo, String> {
    let eng = engine_lock(&state);
    let s = eng.settings();
    let enabled: Vec<_> = s.radios.iter().filter(|r| r.enabled).collect();
    let show_picker = s.simultaneous_radios && enabled.len() >= 2 && active_profile().is_none();
    let radios = enabled
        .iter()
        .map(|r| RadioLaunchOption {
            id: r.id,
            name: r.name.clone(),
            in_use: profile_in_use(&radio_profile_key(r.id)),
        })
        .collect();
    Ok(RadioLaunchInfo { show_picker, radios })
}

/// The operator picked a radio in the launch picker: relaunch this same binary bound to that
/// radio's profile, then exit. The heavy, delicate startup (log binding, journal restores, radio
/// connect) then runs exactly ONCE with the profile already known from the arg — no shortcuts or
/// env vars for the operator to manage.
#[tauri::command]
fn choose_radio(app: tauri::AppHandle, radio_id: u32) -> Result<(), String> {
    let exe = std::env::current_exe().map_err(|e| e.to_string())?;
    std::process::Command::new(exe)
        .arg("--profile")
        .arg(radio_profile_key(radio_id))
        .spawn()
        .map_err(|e| e.to_string())?;
    // The window on screen right now is the radio picker, not a box the operator sized —
    // `quit_cleanup` must not persist it over the base profile's real geometry (see
    // QUIT_SKIP_GEOMETRY). This exit path never captured geometry before the Cmd+Q fix
    // hooked capture into the quit events, and window_state's docs call that correct.
    QUIT_SKIP_GEOMETRY.store(true, std::sync::atomic::Ordering::SeqCst);
    app.exit(0);
    Ok(())
}

/// Write the fleet-level `simultaneous_radios` flag into the BASE profile's settings.json — the
/// one a fresh, profile-less launch reads to decide whether to show the radio picker. The picker
/// blocks the base window's Settings, so a per-radio window is the ONLY place the operator can
/// reach the toggle; without mirroring it here, the base config keeps the flag ON forever and the
/// picker can never be turned off (the trap). Best-effort; a failure just leaves the old value.
fn persist_simultaneous_to_base(enabled: bool) {
    let base = config_dir_for(None).join("settings.json");
    let mut s = Settings::load(&base);
    if s.simultaneous_radios != enabled {
        s.simultaneous_radios = enabled;
        let _ = s.save(&base);
    }
}

/// Mirror the ROSTER IDENTITY (which radios exist) into the BASE profile's settings.json.
///
/// **This is what makes a THIRD radio reachable.** The per-radio config is seeded from base exactly
/// ONCE (first launch of `r<id>`), and `add_radio` then persists only to the window that ran it. With
/// two radios that never bit: you necessarily add radio 1 in the base config BEFORE `tempo-r0`/
/// `tempo-r1` exist, so both windows are seeded with a complete roster that never changes again.
/// Adding a THIRD radio is the first roster mutation that happens AFTER those dirs exist — so it
/// landed in one settings.json only. The base config (which the launch PICKER reads, and which the
/// picker's own overlay blocks the operator from editing) never learned about it, making the new
/// radio permanently unselectable with no repair path.
///
/// Deliberately mirrors only radios base does not already have, and only their identity + config as
/// created — a radio's per-window CAT/audio edits are NOT pushed back, because each window owns its
/// own radio's live config and base's copy may legitimately differ. `radio_pegged`/`active_radio` are
/// per-window and never touched. Best-effort; a failure just leaves base as it was.
fn persist_roster_to_base(radios: &[tempo_app::settings::RadioProfile]) {
    if bound_radio_id().is_none() {
        return; // the base config itself, or an independent named profile — nothing to mirror
    }
    let base = config_dir_for(None).join("settings.json");
    let mut s = Settings::load(&base);
    let added: Vec<_> = radios
        .iter()
        .filter(|r| !s.radios.iter().any(|b| b.id == r.id))
        .cloned()
        .collect();
    let removed = s
        .radios
        .iter()
        .any(|b| !radios.iter().any(|r| r.id == b.id));
    if added.is_empty() && !removed {
        return;
    }
    s.radios.retain(|b| radios.iter().any(|r| r.id == b.id));
    s.radios.extend(added);
    s.ensure_radio_profiles();
    s.ensure_distinct_radio_ports();
    s.ensure_routing_targets();
    if let Err(e) = s.save(&base) {
        eprintln!("tempo: couldn't mirror the radio roster to the base config: {e}");
    }
}

/// Mirror the ROUTING TABLE (rules + default radio) into the BASE profile's settings.json. Routing
/// is a station-wide decision — which rig does 2 m FM is not a per-window opinion — and the same
/// one-time-seed asymmetry as [`persist_roster_to_base`] would otherwise leave each window routing
/// by a different table. Best-effort.
fn persist_routing_to_base(live: &Settings) {
    if bound_radio_id().is_none() {
        return;
    }
    let base = config_dir_for(None).join("settings.json");
    let mut s = Settings::load(&base);
    if s.routing_rules == live.routing_rules && s.default_radio == live.default_radio {
        return;
    }
    s.routing_rules = live.routing_rules.clone();
    s.default_radio = live.default_radio;
    s.ensure_routing_targets();
    if let Err(e) = s.save(&base) {
        eprintln!("tempo: couldn't mirror the routing table to the base config: {e}");
    }
}

/// The picker's "use one radio" escape: turn simultaneous-radios OFF (in the base config the picker
/// reads) and let this window proceed as the single, band-following instance — the pre-picker
/// behavior. Frontend dismisses the picker after this resolves.
#[tauri::command]
fn use_single_radio() -> Result<(), String> {
    persist_simultaneous_to_base(false);
    Ok(())
}

/// The SHARED data directory that holds the ONE unified logbook across all instances.
/// Default = `<base>/tempo` (the default profile's dir — i.e. the pre-profile location, so an
/// existing `log.adi` stays put and simply becomes the shared one, no migration). Override
/// with `NEXUS_DATA_DIR` to place the shared log on a NAS/Drive-synced folder (a multi-PC shack).
fn shared_data_dir() -> PathBuf {
    match std::env::var_os("NEXUS_DATA_DIR").filter(|s| !s.is_empty()) {
        Some(d) => PathBuf::from(d),
        None => config_base().join("tempo"),
    }
}

/// Where settings are persisted: `<config_dir>/settings.json` — per-instance (profile-suffixed).
fn settings_path() -> PathBuf {
    config_dir().join("settings.json")
}

/// Persisted geometry (logical px) + side-dock of the torn-off band-map window, so the
/// vertical band map reopens where the operator left it instead of re-arranging it every
/// launch. A tiny sibling of settings.json (not part of the big Settings blob — it's pure
/// window state, written from the window-event handler and read at window-open time).
#[derive(serde::Serialize, serde::Deserialize, Clone, Default)]
struct BandmapWindow {
    w: f64,
    h: f64,
    x: f64,
    y: f64,
    /// "left" | "right" | "" (free-floating). When set, the window re-snaps to that edge on open.
    #[serde(default)]
    dock: String,
}

/// Per-window geometry file — keyed by `(slug, instance)` so the two band maps DON'T clobber
/// each other's saved size/position/dock when both are torn off, and so a band map bound to a
/// second radio gets its own rect rather than fighting the first one's.
///
/// `main` keeps the historic `bandmap-window-<slug>.json` name byte-for-byte (zero migration:
/// every rect an operator has already saved keeps loading). `None` means this surface's
/// geometry must NOT be persisted at all — see [`Instance::persists_geometry`].
fn bandmap_window_path(slug: &str, inst: Instance) -> Option<PathBuf> {
    if !inst.persists_geometry() {
        return None;
    }
    let name = match inst {
        Instance::Main => format!("bandmap-window-{slug}.json"),
        other => format!("bandmap-window-{slug}-{other}.json"),
    };
    Some(settings_path().with_file_name(name))
}

/// The band-map surface ("bandmapCw"/"bandmapPhone" + its instance) for a window, or None for
/// any other window.
fn bandmap_key(window: &tauri::WebviewWindow) -> Option<(&str, Instance)> {
    let (slug, inst) = panel_key(window.label())?;
    slug.starts_with("bandmap").then_some((slug, inst))
}

fn load_bandmap_window(slug: &str, inst: Instance) -> Option<BandmapWindow> {
    let g: BandmapWindow =
        serde_json::from_str(&std::fs::read_to_string(bandmap_window_path(slug, inst)?).ok()?)
            .ok()?;
    // Reject a degenerate/blank record so a corrupt file falls back to the default size.
    // LOWER bound only: the upper w/h cap and the x/y sanity check need the live monitor
    // list, so they run at open time — see `sanitize_free_bandmap_rect`.
    (g.w >= 200.0 && g.h >= 200.0).then_some(g)
}

fn save_bandmap_window(slug: &str, inst: Instance, g: &BandmapWindow) {
    let Some(p) = bandmap_window_path(slug, inst) else {
        return;
    };
    if let Ok(txt) = serde_json::to_string(g) {
        if let Some(dir) = p.parent() {
            let _ = std::fs::create_dir_all(dir);
        }
        let _ = std::fs::write(p, txt);
    }
}

/// Snapshot a band-map window's current size+position to its own per-surface file (logical px),
/// preserving its dock choice. Called on close so the next open restores it. No-op otherwise.
fn capture_bandmap_window(window: &tauri::WebviewWindow) {
    let Some((slug, inst)) = bandmap_key(window) else {
        return;
    };
    // A minimized window reports a bogus rect (Windows parks it near -32000,-32000), and
    // closing while minimized — including the main-quit cascade close — used to persist
    // exactly that. Skip the snapshot; the last good rect on disk stays.
    if window.is_minimized().unwrap_or(false) {
        return;
    }
    let scale = window.scale_factor().unwrap_or(1.0);
    let (Ok(size), Ok(pos)) = (window.inner_size(), window.outer_position()) else {
        return;
    };
    let dock = load_bandmap_window(slug, inst)
        .map(|g| g.dock)
        .unwrap_or_default();
    save_bandmap_window(
        slug,
        inst,
        &BandmapWindow {
            w: size.width as f64 / scale,
            h: size.height as f64 / scale,
            x: pos.x as f64 / scale,
            y: pos.y as f64 / scale,
            dock,
        },
    );
}

/// True ⇔ a window whose top-left is at (`px`,`py`) leaves a grabbable sliver of itself
/// on the work area (`wx`,`wy`,`ww`,`wh`). All arguments in the SAME monitor's physical
/// px; `mg` is the reachability margin. The band is INFLATED by `mg` past the left/top
/// edges (Windows' invisible resize borders park a screen-edge window's outer_position a
/// few px off-screen — that must still restore in place) but DEFLATED by `mg` at the
/// right/bottom: the window extends right/down from its top-left, so a top-left past
/// those edges puts NOTHING of it on this monitor.
fn rect_lands_on_work_area(px: f64, py: f64, wx: f64, wy: f64, ww: f64, wh: f64, mg: f64) -> bool {
    px >= wx - mg && px <= wx + ww - mg && py >= wy - mg && py <= wy + wh - mg
}

/// Validate a FREE (un-docked) band map's saved rect against the monitors attached RIGHT
/// NOW. Returns `(w, h, keep_position)`: `keep_position` is true only while the saved
/// top-left still lands on SOME monitor's work area — the monitor it was on may have been
/// unplugged since last session, and replaying its rect verbatim reopened the window
/// fully off-screen with no in-app recovery (the only geometry command is dock left/right
/// ON the window you can't reach). `w`/`h` come back capped to that monitor's work area
/// (the primary's when the position is dropped) so a strip saved 1440 tall can't reopen
/// overhanging a 768-tall laptop. Docked windows never come here — their post-build
/// re-snap to the current work area is the stronger correction.
///
/// Coordinates: the rect is stored in LOGICAL px, but tao resolves a logical position by
/// hit-testing it against EACH candidate monitor scaled by THAT monitor's dpi, first
/// match wins, full monitor rect, primary-monitor CW_USEDEFAULT fallback
/// (tao-0.35.3/src/platform_impl/windows/window.rs:1173-1203 — verified in the
/// 2026-07-30 layout assessment, V6). Under mixed DPI one logical point therefore names
/// a different physical point per monitor, so validate in PHYSICAL px per candidate —
/// mirroring tao's own resolution — rather than trusting any single window's scale factor.
fn sanitize_free_bandmap_rect(app: &tauri::AppHandle, g: &BandmapWindow) -> (f64, f64, bool) {
    // Reachability margin in LOGICAL px (scaled per candidate before use).
    const MARGIN: f64 = 32.0;
    let monitors = app.available_monitors().unwrap_or_default();
    let hit = monitors.iter().find(|m| {
        let sf = m.scale_factor();
        let wa = m.work_area();
        rect_lands_on_work_area(
            g.x * sf,
            g.y * sf,
            wa.position.x as f64,
            wa.position.y as f64,
            wa.size.width as f64,
            wa.size.height as f64,
            MARGIN * sf,
        )
    });
    // Cap w/h (logical) at the landing monitor's work area — or the primary's, where a
    // dropped-position window opens. If no monitor resolves at all (headless/API error),
    // leave w/h as saved; `min_inner_size` still floors them at build.
    let cap = hit.cloned().or_else(|| app.primary_monitor().ok().flatten());
    let (mut w, mut h) = (g.w, g.h);
    if let Some(m) = &cap {
        let sf = m.scale_factor();
        let wa = m.work_area();
        w = w.min(wa.size.width as f64 / sf);
        h = h.min(wa.size.height as f64 / sf);
    }
    (w, h, hit.is_some())
}

/// Snap a band-map window to the left/right edge of its monitor's WORK AREA (excludes the
/// taskbar — full monitor size overlapped it) as a full-height strip, keeping its width.
/// Applies the move AND persists the resulting geometry + dock. Best-effort: a window with no
/// resolvable monitor (e.g. not yet mapped) is left as-is.
fn snap_bandmap_to_edge(
    window: &tauri::WebviewWindow,
    side: &str,
) -> Result<BandmapWindow, String> {
    let scale = window.scale_factor().unwrap_or(1.0);
    let cur_w = window
        .inner_size()
        .map(|s| (s.width as f64 / scale).clamp(300.0, 640.0))
        .unwrap_or(420.0);
    let monitor = window
        .current_monitor()
        .map_err(|e| e.to_string())?
        .ok_or_else(|| "no monitor for this window".to_string())?;
    // work_area() is the usable region (taskbar/dock excluded) — unlike size()/position().
    let area = monitor.work_area();
    let mw = area.size.width as f64 / scale;
    let mh = area.size.height as f64 / scale;
    let mx = area.position.x as f64 / scale;
    let my = area.position.y as f64 / scale;
    let w = cur_w;
    let h = mh;
    let x = if side == "left" { mx } else { mx + mw - w };
    let g = BandmapWindow {
        w,
        h,
        x,
        y: my,
        dock: side.to_string(),
    };
    window
        .set_size(tauri::LogicalSize::new(w, h))
        .map_err(|e| e.to_string())?;
    window
        .set_position(tauri::LogicalPosition::new(x, my))
        .map_err(|e| e.to_string())?;
    if let Some((slug, inst)) = bandmap_key(window) {
        save_bandmap_window(slug, inst, &g);
    }
    Ok(g)
}

/// Where the ADIF logbook is persisted: the SHARED data dir (NOT the per-profile config
