/// Tempo's proposed calling-frequency band plan (HF + VHF/UHF), for the band
/// selector. Each entry is General-legal + clear of the existing watering holes.
#[tauri::command(async)]
fn get_band_plan(
    state: State<'_, SharedEngine>,
) -> Result<Vec<tempo_app::bandplan::BandChannel>, String> {
    // Tier-aware (FT8/FT4 → the standard WSJT-X watering holes; FT1/DX1 →
    // native plan) WITH the operator's Settings ▸ Frequencies overrides applied
    // — the band picker must show the dials the engine will actually QSY to.
    Ok(engine_lock(&state).band_plan())
}

/// Set the operator's amateur license class (Technician/General/Extra/Open) — drives the
/// transmit-privilege lockout + the licensed-segment band dropdown. Used by the first-run
/// wizard and Settings.
#[tauri::command(async)]
fn set_license_class(state: State<'_, SharedEngine>, class: String) -> Result<AppSnapshot, String> {
    let mut eng = engine_lock(&state);
    eng.set_license_class(&class);
    if let Err(e) = eng.settings().save(&settings_path()) {
        eprintln!("tempo: failed to persist license class: {e}");
    }
    Ok(eng.snapshot())
}

/// The bands the phone/CW dropdown offers `class` in `mode`, each parked at its licensed
/// home dial. Split out of [`get_licensed_band_plan`] so the list and the privilege filter
/// that trims it can be driven directly by a test, with no engine and no Tauri state — the
/// band that is MISSING from a list is invisible to every test that goes through the command.
fn licensed_bands(
    class: tempo_app::settings::LicenseClass,
    mode: tempo_app::settings::OperatingMode,
) -> Vec<tempo_app::bandplan::BandChannel> {
    use tempo_app::bandplan::BandChannel;
    use tempo_app::settings::OperatingMode;
    const BANDS: &[(&str, &str)] = &[
        ("160m", "HF"),
        ("80m", "HF"),
        ("40m", "HF"),
        ("30m", "HF"),
        ("20m", "HF"),
        ("17m", "HF"),
        ("15m", "HF"),
        ("12m", "HF"),
        ("10m", "HF"),
        ("6m", "VHF"),
        // 4 m is IARU Region 1 only — the US has no allocation at any class (#75). It sits
        // here rather than being left to the FT dropdown because the privilege filter below
        // is what decides who sees it: a US class holds no 4 m segment and never sees the
        // row, while the non-US `Open` class does, in SSB and CW as well as in FT8.
        ("4m", "VHF"),
        ("2m", "VHF"),
        ("1.25m", "VHF"),
        ("70cm", "UHF"),
        // Batch 3: the named microwave bands. Per-class privilege filtering below keeps
        // each operator's dropdown honest automatically — a band whose class holds no
        // segment (9 cm for every US class) is omitted for them and present for Open.
        ("33cm", "UHF"),
        ("23cm", "UHF"),
        ("13cm", "UHF"),
        ("9cm", "UHF"),
        ("6cm", "UHF"),
        ("3cm", "UHF"),
        ("1.25cm", "UHF"),
    ];
    let mut out = Vec::new();
    for (band, group) in BANDS {
        // PHONE goes through THE phone home (`privileges::phone_home`), which lifts an LSB
        // home clear of the segment edge — the bare edge is a dial the transmit gate refuses,
        // and this command recomputing it from `segment_start` is how the dropdown used to
        // publish an unkeyable 7.1250 for 40 m. Sideband comes from the same answer.
        // CW parks in the ACTIVITY window (14.030, not the dead 14.000 edge), clamped to the
        // licensed segment start so it never drops below privileges; digital on the start.
        // Sideband is digital-safe USB for both (the rig-mode policy forces CW in the CW
        // section regardless of this field).
        let home = if matches!(mode, OperatingMode::Phone) {
            tempo_app::privileges::phone_home(class, band)
        } else {
            tempo_app::privileges::segment_start(class, band, mode).map(|seg| {
                let dial = if matches!(mode, OperatingMode::Cw) {
                    tempo_app::bandplan::cw_activity_mhz(band).map_or(seg, |a| a.max(seg))
                } else {
                    seg
                };
                (dial, "USB")
            })
        };
        if let Some((dial, sideband)) = home {
            out.push(BandChannel {
                band: band.to_string(),
                group: group.to_string(),
                dial_mhz: dial,
                mode: sideband.to_string(),
                label: format!("{band} · {dial:.3} MHz"),
                note: String::new(),
            });
        }
    }
    out
}

/// The bands the operator may use in the CURRENT operating mode, each parked at the START of
/// their licensed segment (CW-segment start in CW, phone-segment start in Phone) — the
/// per-cockpit band dropdown. Bands with no privilege for this class+mode are omitted; Open
/// shows the conventional starts. (60 m is omitted — it's channelized; tune it manually.)
#[tauri::command(async)]
fn get_licensed_band_plan(
    state: State<'_, SharedEngine>,
    mode: String,
) -> Result<Vec<tempo_app::bandplan::BandChannel>, String> {
    use tempo_app::settings::OperatingMode;
    let eng = engine_lock(&state);
    let class = eng.settings().license_class;
    // RTTY / SSTV / PSK: fixed standard watering-hole channels (like WSJT-X's
    // per-mode dials), license-filtered per band — a Technician sees only the
    // bands their class can key there (RTTY and PSK ride data privileges, SSTV
    // rides phone).
    let lower = mode.to_ascii_lowercase();
    if lower == "rtty" || lower == "sstv" || lower == "psk" {
        let (plan, priv_mode) = if lower == "rtty" {
            (tempo_app::bandplan::rtty_band_plan(), OperatingMode::Digital)
        } else if lower == "psk" {
            (tempo_app::bandplan::psk_band_plan(), OperatingMode::Keyboard)
        } else {
            (tempo_app::bandplan::sstv_band_plan(), OperatingMode::Phone)
        };
        return Ok(plan
            .into_iter()
            .filter(|c| {
                // Channel band ids may carry a suffix ("2m-call") — privilege-check
                // the base band, via THE canonicaliser (one home, not a hand-split).
                let base = tempo_app::bandplan::canonical_band(&c.band);
                tempo_app::privileges::segment_start(class, &base, priv_mode).is_some()
            })
            .collect());
    }
    // The caller (the cockpit) passes its mode explicitly — the engine's operating_mode is
    // set asynchronously on section entry, so reading it here would race the first mount.
    let mode = match lower.as_str() {
        "phone" => OperatingMode::Phone,
        "cw" => OperatingMode::Cw,
        _ => OperatingMode::Digital,
    };
    Ok(licensed_bands(class, mode))
}

/// Change band / dial frequency / mode live (does not reset the operating mode).
/// `mode` is "USB" or "FM". Persists, retunes the rig, returns the snapshot.
#[tauri::command(async)]
fn set_frequency(
    state: State<'_, SharedEngine>,
    dial_mhz: f64,
    band: String,
    mode: String,
) -> Result<AppSnapshot, String> {
    let mut eng = engine_lock(&state);
    eng.set_frequency(dial_mhz, &band, &mode);
    if let Err(e) = eng.settings().save(&settings_path()) {
        eprintln!("tempo: failed to persist frequency: {e}");
    }
    Ok(eng.snapshot())
}

/// An SSTV strip pick / dial commit: claim the Phone section (SSTV rides Phone) and QSY
/// atomically, so the radio loop never applies the OLD section's mode policy at the new dial
/// (picking 20 m SSTV from RTTY used to land DATA-L at 14.230). Persists like `set_frequency`.
#[tauri::command(async)]
fn sstv_tune(
    state: State<'_, SharedEngine>,
    dial_mhz: f64,
    band: String,
    mode: String,
) -> Result<AppSnapshot, String> {
    let mut eng = engine_lock(&state);
    eng.sstv_tune(dial_mhz, &band, &mode);
    if let Err(e) = eng.settings().save(&settings_path()) {
        eprintln!("tempo: failed to persist frequency: {e}");
    }
    Ok(eng.snapshot())
}

/// Park the dial on one of the APP's OWN fixed channels — the ISS SSTV auto-arm's 145.800 FM.
/// Identical to `set_frequency` on the radio; it differs only in what the per-(band, mode)
/// dial memory makes of it. An app-driven auto-tune is not the operator's dial in that mode,
/// so it is never remembered — and the operator dial it displaces is banked on the way in
/// (the auto-arm restores their own dial through `set_frequency` at LOS, because that one IS
/// theirs). Persists, retunes, returns the snapshot.
#[tauri::command(async)]
fn tune_channel(
    state: State<'_, SharedEngine>,
    dial_mhz: f64,
    band: String,
    mode: String,
) -> Result<AppSnapshot, String> {
    let mut eng = engine_lock(&state);
    eng.tune_channel(dial_mhz, &band, &mode);
    if let Err(e) = eng.settings().save(&settings_path()) {
        eprintln!("tempo: failed to persist frequency: {e}");
    }
    Ok(eng.snapshot())
}

/// Band pick by NAME — the CW/Phone cockpit band dropdowns (`BandPicker`). The engine lands
/// on the last dial the operator used on that band in that mode THIS SESSION, else the same
/// licensed default the dropdown always used (`get_licensed_band_plan`'s own dial, so an
/// unremembered band is byte-for-byte the old behaviour). Every explicit-frequency path keeps
/// calling `set_frequency`: a typed MHz, a spot's frequency or a band-plan channel stays
/// authoritative, with no memory overlay. `mode` = the cockpit's mode (race-safe on entry,
/// like `get_licensed_band_plan`); None = the engine's current operating mode. Persists,
/// retunes, returns the snapshot.
#[tauri::command(async)]
fn pick_band(
    state: State<'_, SharedEngine>,
    band: String,
    mode: Option<String>,
) -> Result<AppSnapshot, String> {
    let mut eng = engine_lock(&state);
    eng.pick_band(&band, mode.as_deref());
    if let Err(e) = eng.settings().save(&settings_path()) {
        eprintln!("tempo: failed to persist frequency: {e}");
    }
    Ok(eng.snapshot())
}

/// Set the per-section operating mode — the rig-mode policy. "digital" obeys the rig
/// (FT8/FT4 default); "phone" forces USB/LSB by band; "cw" forces CW. The phone/CW
/// operating sections call this so the rig follows; the radio loop applies it on the
/// next tune. `follow_freq` = true when the operator clicks an actual operating-section tab
/// (QSY to that mode's home freq); false for incidental nav and the Needed click. Persists,
/// returns the snapshot.
#[tauri::command(async)]
fn set_operating_mode(
    state: State<'_, SharedEngine>,
    mode: String,
    follow_freq: bool,
) -> Result<AppSnapshot, String> {
    let mut eng = engine_lock(&state);
    eng.set_operating_mode(&mode, follow_freq);
    if let Err(e) = eng.settings().save(&settings_path()) {
        eprintln!("tempo: failed to persist operating mode: {e}");
    }
    Ok(eng.snapshot())
}

/// Work a spotted station (the Needed click): set the operating mode AND QSY to the spot's
/// exact frequency atomically (one engine lock, one round-trip) — so the rig can't end up in
/// the new mode at the old dial, and the UI never sees a half-applied state. Persists,
/// returns the snapshot.
#[tauri::command(async)]
fn work_spot(
    state: State<'_, SharedEngine>,
    spots: State<'_, SharedSpots>,
    mode: String,
    freq_mhz: f64,
    band: String,
    call: Option<String>,
    tier: Option<String>,
) -> Result<AppSnapshot, String> {
    // A digital spot names its protocol (FT8/FT4). The tier switch must happen under the
    // SAME engine lock as the QSY: as two commands, the radio loop could tick in the gap
    // and command the tier's default dial to the rig before the spot's exact frequency
    // (operator report, 2026-08-09 — "hitting a default first, then switching", with the
    // stale read-back able to race the correction on slow serial).
    let tier: Option<Tier> = match tier {
        Some(t) => Some(
            serde_json::from_value(serde_json::Value::String(t.clone()))
                .map_err(|_| format!("invalid tier {t:?}"))?,
        ),
        None => None,
    };
    // Pile-up SPLIT: if the freshest cluster spot for this call names a listening
    // offset ("UP 2" / "QSX …"), configure rig split so TX lands where the DX is
    // listening — the N1MM behavior, using the spot we already hold. Tolerant
    // lookup (3Y0J/MM matches 3Y0J); no spot or no offset → simplex.
    let split_up_khz = call.as_deref().and_then(|c| {
        let c = c.to_uppercase();
        // Slash-boundary tolerant identity ONLY ("3Y0J" ⇔ "3Y0J/MM") — bare prefix
        // matching would let "K9A" pick up "K9AB"'s spot (a different station).
        let same_station = |dx: &str| {
            dx == c || dx.starts_with(&format!("{c}/")) || c.starts_with(&format!("{dx}/"))
        };
        spots.lock().ok().and_then(|buf| {
            buf.recent_within(
                std::time::Instant::now(),
                std::time::Duration::from_secs(1800),
            )
            .into_iter()
            .filter(|cs| {
                same_station(&cs.dx_call.to_uppercase())
                    // The spot must be for THIS frequency neighborhood — a 20 m CW
                    // spot's split must not apply to the same call worked on 40 m.
                    && (cs.freq_mhz() - freq_mhz).abs() < 0.05
            })
            .find_map(|cs| cs.split_offset_khz())
        })
    });
    let mut eng = engine_lock(&state);
    eng.work_spot_tiered(tier, &mode, freq_mhz, &band, split_up_khz);
    eng.note_work_call(call); // cross-window prefill hint (pop-out band map → main window log)
    if let Err(e) = eng.settings().save(&settings_path()) {
        eprintln!("tempo: failed to persist worked spot: {e}");
    }
    Ok(eng.snapshot())
}

/// Queue CW to transmit (CAT keyer path). `text` is an F-key macro template or literal
/// type-ahead; the engine expands it (mycall/name/grid + the worked call + a 599 report)
