/// Set (or clear) who is at the key — the seat-swap chip, the Field Day panel's Operator
/// field and the pop-out scoreboard, one write path for all three. A NARROW write — never
/// `apply_settings` (#54: the heavyweight path resets the mode, clears the TX queue and
/// re-derives the TX cycle from the caller's snapshot, and a seat swap happens mid-QSO by
/// definition). Persists; `log_qso` stamps the new operator from the next contact on.
#[tauri::command(async)]
fn set_fd_operator(state: State<'_, SharedEngine>, call: String) -> Result<AppSnapshot, String> {
    let mut eng = engine_lock(&state);
    let s = eng.set_fd_operator(call);
    if let Err(e) = s.save(&settings_path()) {
        eprintln!("tempo: failed to persist field day operator: {e}");
    }
    Ok(eng.snapshot())
}

/// Replace the blocked-callsigns list (the Alt-double-click gesture + the Settings
/// editor's one write path). A NARROW write — never `apply_settings` (#54: the heavyweight
/// path resets the mode and clears the TX queue, and this gets clicked mid-QSO). Persists;
/// the auto-responder reads the list on the next slot.
#[tauri::command(async)]
fn set_blocked_calls(
    state: State<'_, SharedEngine>,
    calls: Vec<String>,
) -> Result<AppSnapshot, String> {
    let mut eng = engine_lock(&state);
    eng.set_blocked_calls(calls);
    if let Err(e) = eng.settings().save(&settings_path()) {
        eprintln!("tempo: failed to persist blocked calls: {e}");
    }
    Ok(eng.snapshot())
}

/// Default inner size (CSS px) a pop-out OPENS at, per panel slug — "give this panel
/// plenty of room", not a content minimum. The Operate cockpit (waterfall + Band
/// Activity + roster) needs more room than the narrower insight panels; the band map is
/// tall + narrow (a vertical frequency axis).
///
/// Paired with `PANEL_NATURAL` in ui/src/useScale.ts, which declares the smallest box in
/// which each panel's content is whole (the UI's zoom-fit denominator). The two are NOT
/// the same number — a band map opens 780 tall but its track is height-elastic — and
/// `ui/src/popout-natural.test.ts` parses this table to enforce the relation that must
/// hold between them (natural ≤ default inner, and natural ≤ min inner ÷ the 65% zoom
/// floor). Extracted from `open_panel_window`'s if/else chain, literal for literal, so
/// that guard has a table to read.
fn panel_default_inner(slug: &str) -> (f64, f64) {
    match slug {
        "operate" => (1140.0, 760.0),
        "bandmapPhone" | "bandmapCw" => (420.0, 780.0),
        "fieldday" => (560.0, 760.0), // the scoreboard: operator + tiles + sections board
        "waterfall" => (900.0, 300.0), // a wide, short monitoring strip
        _ => (760.0, 660.0),
    }
}

/// Smallest inner size (CSS px) a pop-out can be dragged to. The UI's zoom floor is 65%,
/// so this size divided by 0.65 is the largest content box that window can ever show —
/// see `panel_default_inner` for the guard that holds the two sides together.
fn panel_min_inner(slug: &str) -> (f64, f64) {
    match slug {
        "waterfall" => (380.0, 180.0),
        _ => (420.0, 360.0),
    }
}

/// Open (or focus) a standalone OS window showing one panel — multi-monitor
/// tear-off. The detached window loads the app at `?panel=<panel>` and renders just
/// that panel against the same shared engine the main window uses.
///
/// `instance` addresses WHICH surface of that panel (see [`chains`]): absent/`main` is the one
/// window that has always existed, `w<n>` is an extra unbound board. Omitting it is the entire
/// existing call surface, and produces a byte-identical label and URL — zero migration.
#[tauri::command]
async fn open_panel_window(
    app: tauri::AppHandle,
    panel: String,
    instance: Option<String>,
) -> Result<(), String> {
    let slug: String = panel
        .chars()
        .filter(|c| c.is_ascii_alphanumeric())
        .collect();
    if slug.is_empty() {
        return Err("invalid panel".into());
    }
    // The instance is REJECTED when malformed, never stripped. The slug filter above is the
    // cautionary tale: it silently drops non-alphanumerics, which is why `operate-2`,
    // `operate:2` and `operate2` all collapse onto one window. That is now harmless (the slug
    // can never contain the `-` that separates an instance) but must not be repeated here — a
    // typo'd token that got coerced would address a different radio.
    let inst = match instance.as_deref() {
        None => Instance::Main,
        Some(token) => Instance::parse(token)?,
    };
    // HARD GATE — see `chains::openable`.
    chains::openable(inst)?;
    let label = panel_label(&slug, inst);
    // Already open → just focus it (one window per SURFACE — distinct instances of the same
    // panel are distinct windows).
    if let Some(w) = app.get_webview_window(&label) {
        let _ = w.set_focus();
        return Ok(());
    }
    // Friendly window title so multi-monitor users can tell torn-off windows apart.
    let title = match slug.as_str() {
        "connect" => "Nexus — Connect".to_string(),
        "dxped" => "Nexus — DXpeditions".to_string(),
        "needed" => "Nexus — Needed".to_string(),
        "operate" => "Nexus — Operate".to_string(),
        "fieldday" => "Nexus — Field Day".to_string(),
        "waterfall" => "Nexus — Waterfall".to_string(),
        "bandmapPhone" => "Nexus — Band map (Phone)".to_string(),
        "bandmapCw" => "Nexus — Band map (CW)".to_string(),
        other => format!("Nexus — {other}"),
    };
    let is_bandmap = slug == "bandmapPhone" || slug == "bandmapCw";
    // The band map reopens where the operator left it (size + position), so a Windows-snapped
    // vertical strip on the side survives restarts. Other pop-outs keep their fixed defaults.
    let saved = if is_bandmap {
        load_bandmap_window(&slug, inst)
    } else {
        None
    };
    // A docked window re-snaps to the CURRENT monitor work area AFTER build (so a resolution
    // change since last session can't strand it off-screen); a FREE window's rect is validated
    // against the live monitor list below. (It used to be replayed verbatim — un-docking was
    // what removed the only safety net, and a rect saved on a since-unplugged monitor reopened
    // fully off-screen.)
    let docked_side = saved
        .as_ref()
        .map(|g| g.dock.clone())
        .filter(|d| d == "left" || d == "right");
    // FREE rect: keep the position only while its top-left still lands on some monitor's work
    // area, and cap w/h at that work area. Docked rects skip this — their re-snap is stronger.
    let free = match (&saved, &docked_side) {
        (Some(g), None) => Some(sanitize_free_bandmap_rect(&app, g)),
        _ => None,
    };
    let (w, h) = if let Some((w, h, _)) = free {
        (w, h)
    } else if let Some(g) = &saved {
        (g.w, g.h)
    } else {
        panel_default_inner(&slug)
    };
    let (min_w, min_h) = panel_min_inner(&slug);
    // `instance` is a SEPARATE query parameter, never baked into the slug — the slug filter
    // would strip the separator and alias it. Appended only above `main`, so every window that
    // is openable today keeps the exact URL it has always had.
    let url = match inst {
        Instance::Main => format!("index.html?panel={slug}"),
        other => format!("index.html?panel={slug}&instance={other}"),
    };
    let mut builder = tauri::WebviewWindowBuilder::new(
        &app,
        &label,
        tauri::WebviewUrl::App(url.into()),
    )
    .title(title)
    .inner_size(w, h)
    .min_inner_size(min_w, min_h);
    if let Some(g) = &saved {
        if matches!(free, Some((_, _, false))) {
            // FREE window whose saved top-left no longer lands on any monitor (unplugged or
            // rearranged since last session): drop the stale position and open centered on
            // the current monitor instead of replaying a rect nothing displays.
            builder = builder.center();
        } else {
            // Open at the saved position. For a FREE (validated) window that's the exact
            // restore; for a DOCKED window it lands it on the RIGHT monitor (multi-monitor)
            // before the re-snap below refines it to THAT monitor's work-area edge — and it's
            // the fallback if the re-snap can't resolve a monitor.
            builder = builder.position(g.x, g.y);
        }
    }
    // Pop-outs are ordinary windows — the operator must be able to send them behind the
    // main UI (a tester couldn't hide the waterfall while it was pinned always-on-top). A
    // future "pin" toggle can call `window.set_always_on_top(true)` on demand.
    let win = builder.build().map_err(|e| e.to_string())?;
    if let Some(side) = docked_side {
        // Re-pin to the edge of the current work area (best-effort; ignore if unmapped) so a
        // resolution change since last session can't strand it off-screen.
        let _ = snap_bandmap_to_edge(&win, &side);
    }
    Ok(())
}

/// Snap the calling band-map window to the left/right edge of its monitor as a full-height
/// vertical strip (the built-in version of the Windows-snap the operator was doing by hand),
/// keeping its current width. `side` = "left" | "right"; anything else un-docks (free-float,
/// just persists the current geometry). The dock + geometry persist so it restores on relaunch.
#[tauri::command]
fn dock_bandmap_window(window: tauri::WebviewWindow, side: String) -> Result<(), String> {
    if side == "left" || side == "right" {
        snap_bandmap_to_edge(&window, &side)?;
        return Ok(());
    }
    // Un-dock: leave the window where it is, just clear the dock flag (per-surface) so a later
    // open doesn't re-snap it. Persist the current geometry.
    //
    // NOTE for a non-persisting surface (`w<n>`): dock rides in the same file as the rect, so
    // both load and save no-op and the un-dock is in-memory only — the surface re-docks on every
    // open. That is the accepted price of "never persist a recycled instance" (the alternative,
    // GC-on-boot, risks a later `w3` inheriting a stranger's rect). Safe either way: the path is
    // `None` on BOTH sides, so a `w<n>` can never read or clobber `main`'s file. Unreachable
    // today — `w<n>` windows are refused in `open_panel_window`.
    capture_bandmap_window(&window);
    if let Some((slug, inst)) = bandmap_key(&window) {
        let mut g = load_bandmap_window(slug, inst).unwrap_or_default();
        g.dock = String::new();
        save_bandmap_window(slug, inst, &g);
    }
    Ok(())
}

/// Initiate a directed QSO with a specific station (the UI "work this station"
/// action). Enters QSO mode answering `call`. `message`/`snr` are the exact
/// decoded line the operator double-clicked (when available) so the auto-sequencer
/// jumps to the correct next Tx — WSJT-X double-click semantics — instead of
/// restarting at the grid. Returns the refreshed snapshot.
#[tauri::command(async)]
fn call_station(
    state: State<'_, SharedEngine>,
    call: String,
    grid: Option<String>,
    message: Option<String>,
    snr: Option<i32>,
    freq: Option<f32>,
) -> Result<AppSnapshot, String> {
    let mut eng = engine_lock(&state);
    // Working a station keys a standard structured message (your grid in Tx1) — refuse
    // without a valid callsign + grid so we never emit a grid-less directed call. The
    // mode plugin decides which tiers are gated (Capabilities::structured_identity).
    eng.structured_tx_ready(true)?;
    let g = grid.as_deref().map(str::trim).filter(|s| !s.is_empty());
    let msg = message.as_deref().map(str::trim).filter(|s| !s.is_empty());
    // `freq` = the decoded station's audio offset (Hz); move our RX/TX onto it (WSJT-X
    // double-click). Ignore non-positive values (no usable frequency).
    let dx_freq = freq.filter(|f| *f > 0.0);
    eng.call_station_ctx(&call, g, msg, snr, dx_freq)?;
    Ok(eng.snapshot())
}

/// Toggle Skip Tx1 (WSJT-X parity). Session-only — the engine flag resets to off each
/// launch (not persisted), matching WSJT-X; the UI holds its own session state to match.
#[tauri::command(async)]
fn set_skip_tx1(state: State<'_, SharedEngine>, enabled: bool) -> Result<(), String> {
    state
        .lock()
        .map_err(|e| e.to_string())?
        .set_skip_tx1(enabled);
    Ok(())
}

/// Switch the top-level operating area: "dx" (FT8/FT4 structured) or "msg"
/// (FT1/DX1 free-text chat). Atomically sets the area-appropriate tier + mode.
#[tauri::command(async)]
fn set_area(state: State<'_, SharedEngine>, area: String) -> Result<AppSnapshot, String> {
    let mut eng = engine_lock(&state);
    eng.set_area(&area);
    if let Err(e) = eng.settings().save(&settings_path()) {
        eprintln!("tempo: set_area save failed: {e}");
    }
    Ok(eng.snapshot())
}

/// Operator "Resend": re-arm the current QSO message so a stalled/uncopied step
/// transmits again on the next TX slot. No-op outside a QSO.
#[tauri::command(async)]
fn qso_resend(state: State<'_, SharedEngine>) -> Result<AppSnapshot, String> {
    let mut eng = engine_lock(&state);
    eng.qso_resend();
    Ok(eng.snapshot())
}

/// Operator in-QSO free text (WSJT-X Tx5): override the next transmission with
/// `text`, directed to the current DX station when known. No-op outside a QSO.
#[tauri::command(async)]
fn qso_freetext(state: State<'_, SharedEngine>, text: String) -> Result<AppSnapshot, String> {
    let mut eng = engine_lock(&state);
    eng.qso_freetext(&text);
    Ok(eng.snapshot())
}

/// Outcome of the operator "Log QSO" button (#100): whether a contact was actually
/// logged (or held for the prompt-to-log popup), plus the fresh snapshot either way.
#[derive(serde::Serialize)]
#[serde(rename_all = "camelCase")]
struct LogQsoOutcome {
    /// False when the engine refused — already logged, no active QSO/DX, or no report
    /// exchanged yet. Every refusal is a deliberate logbook-integrity guard, and the UI
    /// must not claim "Logged QSO" over one: the bool was being discarded here, so the
    /// toast said success for a write that never happened.
    logged: bool,
    snapshot: AppSnapshot,
}

/// Operator "Log QSO": log the active QSO's contact now (inline cockpit button).
#[tauri::command(async)]
fn log_current_qso(state: State<'_, SharedEngine>) -> Result<LogQsoOutcome, String> {
    let mut eng = engine_lock(&state);
    let logged = eng.log_current_qso();
    Ok(LogQsoOutcome {
        logged,
        snapshot: eng.snapshot(),
    })
}

/// Confirm-and-log a QSO held by the prompt-to-log popup. `record` is the
/// (possibly edited) contact. Returns the refreshed snapshot.
#[tauri::command(async)]
fn confirm_pending_log(
    state: State<'_, SharedEngine>,
    record: LoggedQso,
) -> Result<AppSnapshot, String> {
    let mut eng = engine_lock(&state);
    eng.confirm_pending_log(record.into());
    Ok(eng.snapshot())
}

/// Discard a QSO held by the prompt-to-log popup without logging it.
#[tauri::command(async)]
fn discard_pending_log(state: State<'_, SharedEngine>) -> Result<AppSnapshot, String> {
    let mut eng = engine_lock(&state);
    eng.discard_pending_log();
    Ok(eng.snapshot())
}

/// Manually log a contact to the ADIF logbook (the UI "Log QSO" button). Adds in
/// memory and persists to the log file. Returns the refreshed snapshot.
#[tauri::command(async)]
fn log_qso(state: State<'_, SharedEngine>, record: LoggedQso) -> Result<AppSnapshot, String> {
    let call = record.call.clone();
    let (snap, wav) = {
        let mut eng = engine_lock(&state);
        eng.log_qso(record.into());
        // Per-QSO WAV (off by default): grab the recent RX audio under the lock; write it
        // to disk below, after releasing the lock, so the snapshot poll never waits on I/O.
        let wav = eng.settings().save_qso_wav.then(|| eng.recent_rx_pcm());
        (eng.snapshot(), wav)
    };
    if let Some(pcm) = wav {
        if !pcm.is_empty() {
            // Outside the lock (I/O), and the OUTCOME goes back into the engine so the next
            // snapshot poll carries it to the status lane. The QSO itself is already logged, so a
            // failed recording must never fail this command — that would tell the operator the
            // contact was lost when it was not.
            let outcome = write_qso_wav(&call, &pcm).err();
            if let Some(e) = &outcome {
                eprintln!("nexus: {e}");
            }
            engine_lock(&state).set_recording_warning(outcome);
        }
    }
    Ok(snap)
}

/// The full logbook as serializable contacts (for the UI log view). Each row
/// carries the cty.dat-RESOLVED entity for its callsign — the award identity
/// the UI compares on; the stored free-text COUNTRY is display only (QRZ and
/// cty.dat spell entities differently, which made the DXCC totals disagree and
/// the NEW ONE badge fire on every German/Russian contact forever).
#[tauri::command(async)]
fn get_log(state: State<'_, SharedEngine>) -> Result<Vec<LoggedQso>, String> {
    let eng = engine_lock(&state);
    Ok(eng
        .get_log()
        .into_iter()
        .map(|r| {
            let mut q = LoggedQso::from(r);
            q.entity = propagation::dxcc::resolve(&q.call).map(|i| i.entity.to_string());
            q
        })
        .collect())
}

/// The cty.dat-resolved DXCC entity for a callsign, or null — the log-entry
/// form keys its "new one" badge on this, not on the QRZ country string.
#[tauri::command]
fn resolve_entity(call: String) -> Option<String> {
    propagation::dxcc::resolve(&call).map(|i| i.entity.to_string())
}

/// Every entity name paired with its cty.dat representative location, as
/// `[name, lat, lon]` — the fallback that lets a pane print an azimuth beside a
/// country for a station that never sent a grid.
///
/// **Coordinates, not bearings, deliberately.** A bearing depends on the operator's
/// own grid, which they can change in Settings at any moment; a table of
/// pre-computed headings fetched once at mount would then be silently wrong on
/// every row. Coordinates are grid-independent, so they cache for the life of the
/// window and the bearing is re-derived in the UI from whatever `mygrid` is now.
#[tauri::command]
fn dxcc_entity_locations() -> Vec<(String, f64, f64)> {
    propagation::dxcc::entity_locations()
        .into_iter()
        .map(|(name, lat, lon)| (name.to_string(), lat, lon))
        .collect()
}

/// Every current DXCC entity name (sorted), for the decode panes' "hide any entity" picker
/// (F4MQS) — the full ~340-entity table behind the curated quick-pick 18.
#[tauri::command]
fn dxcc_entity_names() -> Vec<String> {
    propagation::dxcc::dxcc_entity_names()
        .into_iter()
        .map(str::to_string)
        .collect()
}

/// Edit logbook entry `index` (oldest-first, as returned by `get_log`) — a
/// correction. Confirmation/credit/upload state is preserved by the engine.
/// Returns the refreshed snapshot.
#[tauri::command(async)]
fn edit_qso(
    state: State<'_, SharedEngine>,
    index: usize,
    record: LoggedQso,
) -> Result<AppSnapshot, String> {
    let mut eng = engine_lock(&state);
    if !eng.update_qso(index, record.into()) {
        return Err("That contact no longer exists — reload the log and try again.".into());
    }
    Ok(eng.snapshot())
}

/// What a `via` argument MEANS on [`mark_qsl_sent`] — the one decision the command layer owns
/// in the #180 sandwich (UI `'B'|'D'|'E'|null` → here → `Engine::mark_qsl_sent(.., Option<QslVia>)`).
///
/// EXACTLY ONE VALUE WITHDRAWS THE MARK: `null`, which the UI sends from its own explicit
/// "clear" menu entry. Everything else must name a real method or be refused — including the
/// EMPTY string, and that arm is the safety of the whole thing rather than a nicety. Empty is
/// the select's PLACEHOLDER, the state the control sits in when the operator has chosen
/// nothing; it is a non-choice, not a decision, and honouring it as a withdrawal would erase
/// a mark nobody asked to erase. Same loss as reading a typo as a withdrawal, and likelier:
/// a placeholder is a value the UI can emit by accident, and a typo is not.
///
/// So: `None` clears; an unknown or empty non-null value is an error the caller must fix.
fn qsl_via_arg(via: Option<&str>) -> Result<Option<tempo_core::logbook::QslVia>, String> {
    let Some(raw) = via else {
        return Ok(None); // the explicit withdrawal, and the only one
    };
    let code = raw.trim();
    if code.is_empty() {
        return Err(
            "No QSL-sent method given — use B, D, or E, or the menu's Clear entry to \
             withdraw the mark."
                .into(),
        );
    }
    tempo_core::logbook::QslVia::from_code(code)
        .map(Some)
        .ok_or_else(|| format!("Unknown QSL-sent method '{code}' — use B, D, or E."))
}

/// Mark logbook entry `index` (oldest-first, as returned by `get_log`) as
/// QSL-sent — operator-declared truth that a card/request was sent `via`
/// "B"(ureau) / "D"(irect) / "E"(lectronic), dated now. A request is NOT a
/// confirmation: this never flips `confirmed`/`awardConfirmed`. Returns the
/// refreshed snapshot.
///
/// `via: null` — and ONLY null — WITHDRAWS the mark instead (#180). Sending is once-only, so
/// before this a mis-click made the three send entries vanish with nothing to put the row back,
/// while the inbound side had `mark_qsl_card(index, false)` all along. See [`qsl_via_arg`] for
/// why an unknown code, and an EMPTY one, are both errors rather than withdrawals.
///
/// ⚠️ The withdrawal is an OPERATOR DECISION and outranks a later ADIF import that still says
/// sent — the core records the cleared state as such so merge can tell "never sent" from
/// "operator un-sent it". Nothing in this layer re-derives the mark or offers an import a way
/// around that: the command forwards the operator's word and nothing else.
#[tauri::command(async)]
fn mark_qsl_sent(
    state: State<'_, SharedEngine>,
    index: usize,
    via: Option<String>,
) -> Result<AppSnapshot, String> {
    let via = qsl_via_arg(via.as_deref())?;
    let mut eng = engine_lock(&state);
    if !eng.mark_qsl_sent(index, via) {
        return Err("That contact no longer exists — reload the log and try again.".into());
    }
    Ok(eng.snapshot())
}

/// Record whether a PAPER QSL card arrived for logbook entry `index` (#152).
///
/// The operator is the only authority for this: LoTW, eQSL and QRZ report their own
/// confirmations and Nexus syncs those, but nothing knows a card reached a letterbox. It is
/// award-eligible — `QslRcvd::award` is card OR LoTW — so leaving it unrecordable left the
/// awards view understating what the operator can actually claim.
#[tauri::command(async)]
fn mark_qsl_card(
    state: State<'_, SharedEngine>,
    index: usize,
    received: bool,
) -> Result<AppSnapshot, String> {
    let mut eng = engine_lock(&state);
    if !eng.mark_qsl_card(index, received) {
        return Err("That contact no longer exists — reload the log and try again.".into());
    }
    Ok(eng.snapshot())
}

/// Delete logbook entry `index` (oldest-first, as returned by `get_log`). Returns
/// the refreshed snapshot. Indices shift after a delete — the UI reloads the log.
#[tauri::command(async)]
fn delete_qso(state: State<'_, SharedEngine>, index: usize) -> Result<AppSnapshot, String> {
    let mut eng = engine_lock(&state);
    if !eng.delete_qso(index) {
        return Err("That contact no longer exists — reload the log and try again.".into());
    }
    Ok(eng.snapshot())
}

/// Purge the ENTIRE logbook — delete every contact and truncate the ADIF file to
/// an empty log. Destructive and irreversible; the UI gates this behind an explicit
/// confirmation dialog. Returns the number of contacts removed (for the toast).
#[tauri::command(async)]
fn purge_log(state: State<'_, SharedEngine>) -> Result<usize, String> {
    let mut eng = engine_lock(&state);
    let removed = eng.clear_logbook();
    // `clear_logbook` also resets the LoTW/eQSL sync cursors (see its doc comment:
    // an incremental cursor is a lie about an empty log). Persist that here — the
    // engine holds settings, the command layer owns the file.
    if let Err(e) = eng.settings().clone().save(&settings_path()) {
        conn_log(
            "LoTW",
            "error",
            format!("failed to reset the sync cursor after a purge: {e}"),
        );
    }
    Ok(removed)
}

/// Whether a logged QSO was made through a satellite (`PROP_MODE=SAT`) — the
/// flag the award/needs folds state per record so satellite grid credit lands in
/// the Satellite-VUCC buckets, never the per-band ones.
///
/// Since 2026-08-10 `Engine::log_qso` WRITES the pair itself: a contact logged
/// on the held bird's downlink passband, with a designator LoTW accepts, gets
/// `PROP_MODE=SAT` + `SAT_NAME` stamped as a pair (see the stamp block in
/// `log_qso` for the three guards). Records arriving tagged (imports, hand
/// repairs) are carried verbatim as before. Residual: a bird with no derivable
/// designator (ISS) stays untagged — a guessed SAT_NAME breaks TQSL signing.
/// Pinned by `a_contact_logged_during_a_pass_earns_satellite_credit`,
/// `a_two_metre_satellite_contact_is_credited_to_satellite_vucc` and
/// `the_satellite_stamp_splits_the_grid_fold_on_the_downlink_passband`.
fn qso_is_sat(prop_mode: Option<&str>) -> bool {
    prop_mode.is_some_and(|p| p.trim().eq_ignore_ascii_case("SAT"))
}

/// DXCC-first award progress from the logbook (cty.dat-resolved): entities +
/// entity×band "Challenge" slots worked/confirmed, the per-band breakdown, and
/// the worked-but-unconfirmed "new one" chase. Pure/offline — online LoTW/eQSL/
/// QRZ/ClubLog sync (which would flip `confirmed`) is a later increment.
#[tauri::command(async)]
fn get_awards(state: State<'_, SharedEngine>) -> Result<propagation::AwardSummary, String> {
    let eng = engine_lock(&state);
    let mut awards = propagation::Awards::new();
    // Tell the accumulator our own entity so "First DX" counts only foreign ones.
    awards.set_home_call(&eng.settings().mycall);
    for q in eng.get_log() {
        // Award-eligible confirmation only (LoTW/paper) — eQSL doesn't count; plus
        // whether ARRL has granted DXCC-family credit (DXCC / DXCC_BAND /
        // DXCC_MODE / … — real LoTW exports use the granular codes).
        let credited = q.credit_granted.iter().any(|c| c.starts_with("DXCC"));
        awards.add_qso(
            &q.call,
            &q.band,
            &q.mode,
            q.award_confirmed,
            credited,
            // The paper-card channel alone — IOTA's award gate (the IOTA program
            // accepts cards and Club Log matching, never LoTW).
            q.qsl_rcvd.card,
            q.state.as_deref(),
            q.grid.as_deref(),
            q.ota.iota.as_deref(),
            qso_is_sat(q.prop_mode.as_deref()),
        );
    }
    Ok(awards.summary())
}

/// The geographic slice of the logbook — QSOs by WAC continent, by CQ zone, and a DX-vs-domestic
/// split — the dimensions the frontend `StatsView` can't derive on its own (the stored record has
/// no continent/zone; both re-resolve per callsign here via cty.dat, anchored on the operator's
/// own call for the DX split). The rest of the Statistics dashboard (band/mode/year/hour/state/
/// confirmations) is computed frontend-side from `get_log`. Pure/offline.
#[tauri::command(async)]
fn get_log_stats(state: State<'_, SharedEngine>) -> Result<propagation::LogStats, String> {
    let eng = engine_lock(&state);
    let my_call = eng.settings().mycall.clone();
    let calls: Vec<String> = eng.get_log().into_iter().map(|q| q.call).collect();
    Ok(propagation::compute_log_stats(&calls, &my_call))
}

/// The Journey snapshot — the in-app, beginner-first achievement layer (auto-detected
/// firsts, tiered sub-award ladders toward the big awards, fill-the-map collections,
/// novel ham feats, personal bests, an XP/level spine, and an opt-in weekly streak),
/// computed locally from the log + the operator's grid/power. Async (off the main
/// thread; the log scan can be large). Local-only — no network.
#[tauri::command]
async fn get_journey(
    state: State<'_, SharedEngine>,
) -> Result<propagation::JourneySummary, String> {
    use propagation::model::{Band, ModeClass};
    let eng = engine_lock(&state);
    let s = eng.settings();
    let qsos: Vec<propagation::JourneyQso> = eng
        .get_log()
        .into_iter()
        .map(|r| propagation::JourneyQso {
            call: r.call,
            grid: r.grid,
            state: r.state,
            band: Band::from_label(&r.band),
            mode: ModeClass::from_adif(&r.mode),
            when_unix: r.when_unix as i64,
            // Award-eligible confirmation (LoTW/paper — not eQSL), matching the
            // awards + "first confirmation" semantics.
            confirmed: r.award_confirmed,
            // The Journey "strongest signal" stat is a digital dB SNR concept; parse
            // the numeric report only for DIGITAL QSOs (a phone "59"/CW "599" isn't dB).
            rst_rcvd: if ModeClass::from_adif(&r.mode) == ModeClass::Digital {
                r.rst_rcvd
                    .as_deref()
                    .and_then(|s| s.trim().parse::<i32>().ok())
            } else {
                None
            },
            pota: r
                .ota
                .their_program
                .as_deref()
                .is_some_and(|p| p.eq_ignore_ascii_case("POTA")),
            sota: r
                .ota
                .their_program
                .as_deref()
                .is_some_and(|p| p.eq_ignore_ascii_case("SOTA")),
            // Hunter ladders count DISTINCT park/summit references.
            pota_ref: if r
                .ota
                .their_program
                .as_deref()
                .is_some_and(|p| p.eq_ignore_ascii_case("POTA"))
            {
                r.ota.their_ref.clone()
            } else {
                None
            },
            sota_ref: if r
                .ota
                .their_program
                .as_deref()
                .is_some_and(|p| p.eq_ignore_ascii_case("SOTA"))
            {
                r.ota.their_ref.clone()
            } else {
                None
            },
        })
        .collect();
    let grid = (!s.mygrid.is_empty()).then_some(s.mygrid.as_str());
    Ok(propagation::compute_journey(
        &qsos,
        &s.mycall,
        grid,
        s.station_power_w,
        s.journey_streak_enabled,
        now_unix(),
    ))
}

/// Silent match-failure diagnostics: per-QSO "why isn't this confirmed, and what's
/// the one fix?" + a leverage-ranked rollup, from the log + the last LoTW/eQSL
/// reconcile orphans (this session). Pure/offline; cty.dat resolves each call's
/// DXCC entity for the WAS (R4d) US-family gate.
#[tauri::command(async)]
fn get_confirmation_diagnostics(
    state: State<'_, SharedEngine>,
) -> Result<DiagnosticsReportDto, String> {
    let eng = engine_lock(&state);
    let report = eng.confirmation_diagnostics(now_unix(), |call| {
        propagation::dxcc::resolve(call).map(|i| i.entity.to_string())
    });
    Ok(report.into())
}

/// One raw cluster/RBN spot for the Spots panel (the SpotCollector-style firehose view).
/// UNLIKE the Needed board, this is NOT needs-gated — every recent spot is returned and
/// the UI filters client-side. `mode` is the frequency-derived class (CW/Phone/Digital) that
/// drives the filter chips + privilege gate; `submode` carries the RBN skimmer's specific mode
/// (FT8/FT4/RTTY/PSK/CW) when present, so the panel can show it instead of a bare "Digital".
#[derive(serde::Serialize)]
#[serde(rename_all = "camelCase")]
struct SpotRow {
    call: String,
    /// DXCC entity, "" if the call doesn't resolve.
    entity: String,
    /// CQ zone, 0 if unknown.
    zone: u8,
    /// US state (WAS code), best-effort from the roster's cached grid for a station heard before
    /// (own decodes / PSK Reporter). `None` for a cluster/RBN spot of a station not yet heard with
    /// a grid, or a non-US station — cluster spots carry no grid of their own.
    state: Option<String>,
    /// Band label ("20m"), "" if off the band plan.
    band: String,
    freq_mhz: f64,
    /// Frequency-derived mode CLASS: "CW" | "Phone" | "Digital". Drives the 3-class filter
    /// chips and the privilege gate.
    mode: String,
    /// The SPECIFIC mode a skimmer reported on the RBN wire ("FT8" / "FT4" / "RTTY" / "PSK" /
    /// "CW"), when this spot carries one — so the firehose can distinguish FT8 from FT4 from
    /// RTTY instead of lumping them all as "Digital". `None` for human-node spots (whose
    /// free-text mode is untrusted, per the 21.074-CW doctrine). The UI shows `submode ?? mode`.
    submode: Option<String>,
    spotter: String,
    /// Other spotters of the same DX (multi-endpoint evidence the buffer carries forward).
    corroborators: Vec<String>,
    /// Seconds since the spot was received; -1 if unknown (no receive stamp).
    age_secs: i64,
    comment: String,
    /// True when the operator's license class may TRANSMIT at this spot's frequency in
    /// its mode (privileges::tx_allowed; `Open` class ⇒ always true). Drives the Spots
    /// panel's "my privileges" filter — computed here so the legal band data has ONE
    /// source of truth (the same tables as the TX lockout).
    licensed: bool,
    /// True when at least one voice for this spot — the spotter or a corroborator — is on the
    /// OPERATOR'S OWN CONTINENT.
    ///
    /// The same question the Needed board asks (`propagation::hf_admit_spotters`), asked here
    /// so the Spots panel can offer the operator the same relief: a US station does not need a
    /// row for a JA that only Europe and Asia heard, because that says nothing about a path
    /// from Illinois. Computed in Rust because resolving a callsign to a continent needs
    /// cty.dat, which the UI does not have.
    ///
    /// ⚠️ A FLAG, NOT A FILTER. The row is always sent; the panel decides. Filtering here
    /// would make "where did my spots go" unanswerable from the UI, and the count of what is
    /// being hidden is what keeps the feature honest.
    ///
    /// True when locality cannot be judged at all (an unresolvable operator callsign), which
    /// is `hf_admit_spotters`'s own fail-open posture: an empty panel is a worse answer than
    /// an unfiltered one.
    spotter_local: bool,
    /// Set when this spot is a ONE-WAY transmission — an NCDXF/IARU beacon slot or a W1AW
    /// bulletin — and therefore not workable. The row is still shown (an audible beacon is
    /// real propagation evidence); the UI badges it and never paints a need colour on it.
    /// The matching score suppression lives in `propagation::needalert::rank`, so this field
    /// is a DISPLAY concern only. `None` for an ordinary spot.
    beacon: Option<propagation::beacons::BeaconKind>,
}

/// Raw spot firehose for the Spots panel — every recent spot (CW/Phone/Digital, all
/// sources), newest first, NOT filtered by operator needs. The buffer's age-based
/// retention (≈20 min) bounds the set; the UI applies band/mode/age filters client-side.
#[tauri::command(async)]
fn get_all_spots(spots: State<'_, SharedSpots>, state: State<'_, SharedEngine>) -> Vec<SpotRow> {
    use tempo_app::settings::{LicenseClass, OperatingMode};
    // UNASSISTED mode: no spot may be DISPLAYED either. Ingestion is already gated at the
    // feed callbacks, so the buffer should be empty — this is the belt-and-braces read gate,
    // so the guarantee never depends on a buffer clear having succeeded, and any spot
    // received before the switch flipped is invisible immediately.
    if unassisted() {
        return Vec::new();
    }
    let now = now_unix();
    let recent = match spots.lock() {
        Ok(buf) => buf.recent_within(
            std::time::Instant::now(),
            std::time::Duration::from_secs(1200),
        ),
        Err(_) => return Vec::new(),
    };
    // Take the engine lock ONLY long enough to snapshot what the rows need: the license class,
    // and the roster's cached grid for each spotted call (a station heard before → its grid →
    // its state). Everything expensive below — DXCC resolve, the FCC state lookup, the privilege
    // check and ~8 allocations per row, plus the final sort — then runs with the lock RELEASED.
    //
    // It used to hold the lock across that entire unbounded pass, so every `get_spectrum_row`
    // and every 300 ms `get_snapshot` queued behind a full firehose row-build. Measured at the
    // buffer's 30,000-row cap that hold was ~14-23 ms, which is NOT the operator's ~1 s
    // waterfall stall (that was chased and ruled out on 2026-07-25) — but it is a needless
    // contention point on the app's busiest shared lock, and it grows with band activity.
    //
    // Poison recovers (engine_lock), so the gate always sees real state; the Option
    // shape is kept for the chains below.
    let (class, my_call, roster_grids) = {
        let eng = Some(engine_lock(&state));
        let class = eng
            .as_ref()
            .map(|e| e.settings().license_class)
            .unwrap_or(LicenseClass::Open);
        // The operator's own call decides "my continent" for the locality flag below. Read
        // under the SAME lock as the class, so a settings save mid-build cannot give one row
        // the old callsign and the next the new one.
        let my_call = eng
            .as_ref()
            .map(|e| e.settings().mycall.clone())
            .unwrap_or_default();
        let grids: std::collections::HashMap<String, String> = eng
            .as_ref()
            .map(|e| {
                recent
                    .iter()
                    .filter_map(|cs| {
                        e.roster_grid(&cs.dx_call)
                            .map(|g| (cs.dx_call.clone(), g.to_string()))
                    })
                    .collect()
            })
            .unwrap_or_default();
        (class, my_call, grids)
    };
    let mut rows: Vec<SpotRow> = recent
        .into_iter()
        .map(|cs| {
            let freq = cs.freq_mhz();
            let band = propagation::Band::from_mhz(freq)
                .map(|b| b.label().to_string())
                .unwrap_or_default();
            let (entity, zone) = propagation::dxcc::resolve(&cs.dx_call)
                .map(|i| (i.entity.to_string(), i.cq_zone))
                .unwrap_or_default();
            // US state hint (drives New-State): FCC callsign→state baseline (precise, no grid
            // needed → covers this whole cluster/CW/SSB firehose), refined by the roster's cached
            // decode grid for rovers. See us_state_hint.
            let roster_grid = roster_grids.get(&cs.dx_call).map(String::as_str);
            let state = us_state_hint(&cs.dx_call, roster_grid);
            let age_secs = if cs.received_unix > 0 {
                (now - cs.received_unix as i64).max(0)
            } else {
                -1
            };
            let mode_label = propagation::classify_spot_mode(freq).label();
            let licensed = tempo_app::privileges::tx_allowed(
                class,
                freq,
                match mode_label {
                    "Phone" => OperatingMode::Phone,
                    "CW" => OperatingMode::Cw,
                    _ => OperatingMode::Digital,
                },
            );
            SpotRow {
                call: cs.dx_call.clone(),
                entity,
                zone,
                state,
                band,
                freq_mhz: freq,
                mode: mode_label.to_string(),
                // Trusted specific mode from the RBN skimmer wire, when present (never human
                // free-text). The class-level `mode` above still drives the filter + privilege.
                submode: cs.skimmer_mode().map(str::to_string),
                spotter: cs.spotter.clone(),
                corroborators: cs.corroborators.clone(),
                age_secs,
                comment: cs.comment.clone(),
                licensed,
                spotter_local: {
                    // Every voice for this spot, the spotter first — one on my continent is
                    // enough, exactly as on the Needed board.
                    let mut voices: Vec<&str> = vec![cs.spotter.as_str()];
                    voices.extend(cs.corroborators.iter().map(String::as_str));
                    propagation::hf_admit_spotters(&voices, &my_call).is_some()
                },
                beacon: propagation::beacons::classify(&cs.dx_call, freq),
            }
        })
        .collect();
    // Newest first; unknown-age spots sort last.
    rows.sort_by_key(|r| if r.age_secs < 0 { i64::MAX } else { r.age_secs });
    rows
}

/// The Needed board's DX-cluster / RBN evidence arm: every buffered spot that is
/// WORKABLE-FROM-HERE evidence for the operator, as a `Heard`.
///
/// Lifted out of [`get_need_alerts`] so the LOCALITY GATE inside it is reachable by a
/// test holding a buffer's worth of real spots. The gate's whole job is to DROP rows,
/// and a test of the gate helper alone cannot see whether the board still asks it —
/// which is exactly how a board that had never been wired to one shipped.
///
/// Pure over its inputs: `recent` is the spot buffer's read window, `me_ll` the
/// operator's station lat/lon (`None` when no grid is set), `my_call` their callsign,
/// `license_class` the privilege gate's class.
fn cluster_spot_heards(
    recent: &[tempo_net::cluster::ClusterSpot],
    me_ll: Option<(f64, f64)>,
    my_call: &str,
    license_class: tempo_app::settings::LicenseClass,
) -> Vec<propagation::Heard> {
    let mut out: Vec<propagation::Heard> = Vec::new();
    for cs in recent {
        let freq = cs.freq_mhz();
        let Some(band) = propagation::Band::from_mhz(freq) else {
            continue; // off the band plan → skip
        };
        // ALL independent voices for this DX: the current spotter + the
        // spotters whose earlier reports the buffer's dedup replaced.
        // the buffer's push filter guarantees spotter ∉ corroborators (and no
        // dupes within), so this needs no re-dedup. The HF arm below may REORDER it
        // — it is also what feeds the evidence line.
        let mut voices: Vec<&str> = std::iter::once(cs.spotter.as_str())
            .chain(cs.corroborators.iter().map(|c| c.as_str()))
            .collect();
        // LOCALITY GATE (weak-signal-sleuth principle): a cluster spot is only
        // WORKABLE-FROM-HERE evidence when someone NEAR THE OPERATOR heard it.
        // Applied BEFORE the mode-class filter so CW and SSB spots gate
        // identically. The two bands ask the question at different scales
        // because the propagation does: an Es patch is 100–400 km across, an
        // F2 footprint spans a continent.
        if band.is_vhf() {
            // VHF: how many voices are inside the operator's Es-patch radius,
            // by the skimmer's precise published grid. Needs >= 2 — the PSKR
            // path has required two near receivers all along, but a single
            // near RBN skimmer could still sneak a 6 m CW spot through here
            // (the last uncorroborated hole, the 4U1UN case). A spotter with
            // no known grid can't prove locality → doesn't count.
            let near_spotters = voices
                .iter()
                .filter(|sp| match (propagation::skimmer_grid(sp), me_ll) {
                    (Some(g), Some(me)) => {
                        propagation::geo::maidenhead_to_latlon(g).is_some_and(|rx| {
                            propagation::geo::haversine_km(me, rx)
                                <= propagation::near_me_radius_km(band)
                        })
                    }
                    _ => false,
                })
                .count();
            if near_spotters < 2 {
                continue;
            }
            // …and the DX must be propagation-FAR, not a groundwave local (the
            // 6 m CQ machine 50 km away is spotted by every nearby skimmer,
            // opening or not). Cluster spots carry no grid, so judge by DXCC:
            // a different entity is DX by definition; same-entity falls back to
            // the centroid distance (coarse, but US locals resolve to the same
            // ~country centroid as the operator and correctly read "near").
            let dx_far = match (propagation::dxcc::resolve(&cs.dx_call), me_ll) {
                (Some(info), Some(me)) => {
                    let d = propagation::geo::haversine_km(me, (info.lat, info.lon));
                    let my_entity = propagation::dxcc::resolve(my_call).map(|i| i.entity);
                    let far_enough =
                        my_entity != Some(info.entity) || d >= propagation::VHF_MIN_DX_KM;
                    // …and NOT past the terrestrial ceiling: on 2 m/4 m anything beyond
                    // single-hop Es (~2400 km) reaches only via EME, which a nearby
                    // big-gun's spot doesn't make workable from an ordinary station.
                    let within_terrestrial =
                        propagation::vhf_max_terrestrial_km(band).is_none_or(|max| d <= max);
                    far_enough && within_terrestrial
                }
                _ => false,
            };
            if !dx_far {
                continue;
            }
        } else {
            // HF: at least one voice on the operator's OWN CONTINENT, and that
            // one leads the evidence line. (Operator 2026-08-05: "I am getting
            // spots from JI prefix, which is Japan… the initial intention was to
            // only show those spots that were heard geographically close to me
            // on the HF bands… I would want spots to show up for almost all
            // those spotted in the US.") The constraint is on where the spot was
            // HEARD, not where the DX is: a JA station a US skimmer copied is
            // exactly what he wants and survives this; a JA station only Japan
            // and Europe heard says nothing about a path from EN52 and does not.
            //
            // This is the gate the two "HF keeps the continent-wide cluster"
            // comments (here and in `get_propagation`) always described and that
            // was never actually written — the board's only locality test was
            // `is_vhf`, so on HF the raw worldwide firehose went straight to the
            // scorer. Continent rather than a radius, and the reasoning + the
            // measured cost live on `hf_admit_spotters`.
            let Some(ordered) = propagation::hf_admit_spotters(&voices, my_call) else {
                continue;
            };
            voices = ordered;
        }
        let class = propagation::classify_spot_mode(freq);
        // PRIVILEGE GATE (operator 2026-07-22, "LU6HL on 7.140 shouldn't show"): a station
        // on a frequency the operator may not TRANSMIT to is not a need — the Needed board is
        // a "work these" list, and 7.140 SSB sits in the Extra-only 40 m phone segment a
        // General may not use. SpotsPanel already gates its firehose on the same tables; the
        // Needed board never did, which is the leak. Open (non-US) short-circuits to allowed.
        let op_mode = match class {
            propagation::ModeClass::Cw => tempo_app::settings::OperatingMode::Cw,
            propagation::ModeClass::Phone => tempo_app::settings::OperatingMode::Phone,
            _ => tempo_app::settings::OperatingMode::Digital,
        };
        if !tempo_app::privileges::tx_allowed(license_class, freq, op_mode) {
            continue;
        }
        // CW/Phone on any band; digital on HF only (the missing HF evidence path
        // for a digital op). The need-matcher is demand-driven, so a busy HF FT8
        // firehose only surfaces the stations the operator actually NEEDS.
        let surface = matches!(
            class,
            propagation::ModeClass::Cw | propagation::ModeClass::Phone
        ) || (!band.is_vhf() && matches!(class, propagation::ModeClass::Digital));
        if surface {
            // Evidence line: who spotted it (RBN/cluster path). Cluster
            // lines age out of the buffer at 15 min, so "recently" is the
            // honest stamp without per-spot wall-clock plumbing. On HF
            // `voices` has been reordered so the spotter that ADMITTED the
            // row (the one on the operator's continent) is named first.
            let spotters: Vec<&str> = voices.iter().copied().take(3).collect();
            out.push(propagation::Heard {
                call: cs.dx_call.to_ascii_uppercase(),
                band: band.label().to_string(),
                // UPGRADE the display/routing label from the RBN skimmer wire's structured
                // mode token (RTTY/FT8/FT4) so the board designates the SPECIFIC digital
                // mode, not just "Digital" — the machine-generated wire's leading token,
                // trusted like the OTA feed. Guard on the Digital class so a mistokened wire
                // can never RECLASSIFY across classes (the anti-comment doctrine, 21.074-CW
                // bug); everything else keeps its frequency-derived class label.
                mode: match cs.skimmer_mode() {
                    Some(m @ ("RTTY" | "FT8" | "FT4"))
                        if class == propagation::ModeClass::Digital =>
                    {
                        m.to_string()
                    }
                    _ => class.label().to_string(),
                },
                freq_mhz: Some(freq),
                // The spot's REAL receive time — stamping poll-time made
                // every cluster row read "just now" forever.
                admitted_at: (cs.received_unix > 0).then_some(cs.received_unix as i64),
                evidence: Some(format!(
                    "spotted by {} via cluster/RBN",
                    spotters.join(" + ")
                )),
                grid: None,     // cluster/RBN spots carry no grid…
                us_state: None, // …and `get_need_alerts` fills the FCC state hint in
            });
        }
    }
    out
}

/// Need-aware spotting: rank the stations WORKABLE FROM HERE RIGHT NOW by award
/// value (new DXCC / CQ zone / band-slot / mode). Crucially, the value is the bands
/// you're NOT tuned to — so the evidence is EMPIRICAL near-me reception, not a
/// model: a station counts if a receiver NEAR YOU (PSK Reporter / near-region feed,
/// band-aware radius) is hearing it, plus whatever your own radio is decoding on the
/// current band. (Weak-signal-sleuth: someone local to you actually copied the DX,
/// so the path is open from your QTH too — not "someone in Spain heard the Spanish
/// station.")
#[tauri::command]
async fn get_need_alerts(
    state: State<'_, SharedEngine>,
    live_paths: State<'_, SharedLivePaths>,
    region_paths: State<'_, SharedRegionPaths>,
    spots: State<'_, SharedSpots>,
    ota_cache: State<'_, SharedOtaSpots>,
) -> Result<Vec<propagation::NeedAlert>, String> {
    let mut eng = engine_lock(&state);
    // Two-instance freshness: if the OTHER radio just logged/confirmed something in the shared
    // log, fold it in BEFORE computing needs — otherwise this (possibly monitoring) radio would
    // flag a DXCC/state/grid as needed that the other one already worked. Mtime-gated, so this is
    // a cheap `stat` whenever the file is unchanged.
    eng.sync_shared_log_if_changed();
    let mut needs = propagation::LogNeeds::new();
    for q in eng.get_log() {
        needs.add_qso(
            &q.call,
            &q.band,
            &q.mode,
            q.grid.as_deref(),
            q.state.as_deref(),
            q.award_confirmed,
            qso_is_sat(q.prop_mode.as_deref()),
        );
    }
    let snap = eng.snapshot();
    // Operator "wanted" watch list (W1.5) — captured before the lock drops.
    let wanted_calls = eng.settings().wanted_calls.clone();
    // License class for the privilege gate below — a station on a frequency the operator may not
    // transmit to is not a "need". Open (non-US) short-circuits tx_allowed to true, so no gate.
    let license_class = eng.settings().license_class;
    drop(eng); // nothing below needs the engine — don't hold the hot lock
    let band = snap.radio.band.clone();
    // Your own radio's decodes on the CURRENT band (you are the receiver). These come
    // from the digital modem, so the truthful mode label is the active TIER (FT8/FT4/
    // FT1/DX1) — all of which map to the Digital class for click-to-work routing.
    let tier_mode = format!("{:?}", snap.link.tier).to_uppercase();
    // "Heard by MY radio" is the board's strongest claim and must mean NOW: cap it at 2 minutes
    // of wall clock. The conversion (and the tier-switch refusal it carries) is
    // `own_decode_heards` → `roster_spot_age_secs`.
    const OWN_DECODE_MAX_AGE_SECS: i64 = 120;
    let mut heard: Vec<propagation::Heard> = own_decode_heards(
        &snap.stations,
        snap.radio.slot,
        snap.radio.tr_period_secs,
        &band,
        &tier_mode,
        OWN_DECODE_MAX_AGE_SECS,
    );
    // The real value (empirical evidence, not a model): two complementary signals
    // over the PSK Reporter firehose + near-region feed —
    //   1. heard_near_me: a receiver NEAR YOU is hearing the DX (their signal
    //      reaches you), gated by a band-aware "local to me" radius (Es on VHF is
    //      tighter than F2 on HF);
    //   2. workable_by_getting_out: a third party is hearing a DX in a region your
    //      OWN signal is reaching (who-heard-me reports) on that band — you can
    //      likely work it even if you aren't hearing it yet.
    let now = now_unix() as i64;
    let me_ll = propagation::geo::maidenhead_to_latlon(snap.mygrid.trim());
    // UNASSISTED mode drops both PSK Reporter evidence arms. ARRL's glossary names
    // "PSKReporter" in Spotting/QSO Finding Assistance, so an unassisted entry cannot use
    // other people's reception reports to find stations. The operator's own OUTBOUND uploads
    // keep running: the same glossary says "Generating spotting information for use by other
    // stations is not considered to be spotting assistance."
    //
    // Own-radio decodes (assembled above) are NOT assistance under either ruleset — they are
    // the operator's own receiver — so they stay, and remain the whole Needed board in an
    // unassisted entry.
    if !unassisted() {
        if let Ok(buf) = live_paths.lock() {
            let recent = buf.recent(now, 900);
            if let Some(me) = me_ll {
                heard.extend(propagation::heard_near_me(&recent, me));
            }
            heard.extend(propagation::workable_by_getting_out(&recent, &snap.mycall));
        }
        if let Some(me) = me_ll {
            if let Ok(buf) = region_paths.0.lock() {
                heard.extend(propagation::heard_near_me(&buf.recent(now, 900), me));
            }
        }
    }
    // Privilege-gate the DIGITAL evidence paths (own decodes + PSKR near-region / getting-out)
    // the SAME way the cluster/RBN loop below gates each spot: a band the operator may not
    // TRANSMIT digital on is not a "work these" need. Since the PSKR near-region census now
    // covers HF F2 bands (40/20/17/15/12m), a Technician (no HF digital except 10m) would
    // otherwise see 20/40m FT8 DX as workable needs. Everything in `heard` so far is
    // digital-tier, so gate as Digital at the band's FT8 DIAL (band_digital_mhz — NOT band
    // centre: 80m centre 3.600 sits in General's no-privilege gap). `Open` ⇒ tx_allowed true;
    // General/Extra pass all HF digital, so only restricted classes change. Unparseable band ⇒
    // keep (fail-open, matching get_all_spots' "never wrongly hide" posture).
    heard.retain(|h| {
        propagation::Band::from_label(&h.band).is_none_or(|b| {
            tempo_app::privileges::tx_allowed(
                license_class,
                propagation::band_digital_mhz(b),
                tempo_app::settings::OperatingMode::Digital,
            )
        })
    });
    // CW / Phone (all bands) AND digital on HF come from the DX-cluster + RBN spot
    // firehose, which carries an EXACT frequency (→ click-to-work can QSY to the spot).
    // For a digital HF need the near-region PSKR census now also covers 40/20/17/15/12m
    // (hf_region_topics), so the cluster path here is partly redundant with it — but the
    // cluster still adds the EXACT freq (PSKR is band-level) and every human-node CW/Phone
    // spot. Digital is admitted on HF ONLY here; VHF digital stays out (VHF locality is gated
    // above and Es/MS digital adds noise). The frontend's mode gating still hides CW/Phone
    // rows unless those features are on, so a digital board gains only HF digital. Both the
    // PSKR paths (gated just above) and these cluster spots (gated per-spot below) honor
    // tx_allowed, so a restricted class never sees an un-workable row.
    //
    // UNASSISTED mode skips this whole arm: cluster and RBN spots are callsign-and-frequency
    // identification from other people's receivers, which is the assistance both CQ WW and
    // ARRL name first. Ingestion is already gated at the feed callbacks, so this is the
    // read-side guarantee (see `get_all_spots`).
    if let Some(buf) = spots.lock().ok().filter(|_| !unassisted()) {
        heard.extend(cluster_spot_heards(
            &buf.recent_within(
                std::time::Instant::now(),
                std::time::Duration::from_secs(900),
            ),
            me_ll,
            &snap.mycall,
            license_class,
        ));
    }
    // Fill in the US-state hint from the FCC callsign→state index for every heard call that
    // doesn't already carry one. This is the whole point of the FCC index: a needed New State
    // lights up across the grid-less firehose (cluster / CW / SSB spots, near-me + getting-out
    // reception Heards). A grid-derived state (own decodes) is already set and left untouched.
    for h in heard.iter_mut() {
        if h.us_state.is_none() {
            h.us_state = fcc_state_for_call(&h.call).map(str::to_string);
        }
    }
    let mut alerts = propagation::rank_needs(&heard, &needs, &needs.slots());
    // Never alert on the operator's own call (their PSKR "heard me" echoes can
    // otherwise surface it as a phantom row).
    let me_up = snap.mycall.to_uppercase();
    alerts.retain(|a| a.call != me_up);
    // DXpedition tagging: a heard call that belongs to an ACTIVE announced
    // expedition gets the Dxped chip + a priority nudge — limited-time windows
    // must be findable at a glance on the board. APPENDED (never tags[0]) so the
    // award tier keeps driving the row color. Reads the lock-only cached plan list
    // (warmed by a startup primer + every prop refresh) — NOT the PropCache, which
    // is only populated once the operator visits Connect/DXpeditions. The match is
    // suffix/prefix-tolerant ("3Y0J/MM" still tags as 3Y0J).
    let active = propagation::live::dxped::cached_active_calls(now_unix() as i64);
    if !active.is_empty() {
        for a in &mut alerts {
            let call = a.call.to_uppercase();
            if active
                .iter()
                .any(|act| propagation::live::dxped::call_matches(act, &call))
            {
                a.tags.push(propagation::NeedTag::Dxped);
                // +15 floats expedition rows up WITHIN their award tier without ever
                // crossing into the next one (tier floors are 10/30/50/70/100 — the
                // smallest gap is 20).
                a.priority += 15;
                a.headline = format!("{} · active DXpedition", a.headline);
            }
        }
        alerts.sort_by(|x, y| y.priority.cmp(&x.priority));
    }
    // POTA/SOTA tagging: a heard call that is a LIVE activator (per the hunter
    // feed's cache, <= 10 min fresh) gets the program chip — park chasers spot
    // them on the board at a glance. Appended like Dxped; no priority change
    // (a park is a park — the award tier still drives the row).
    if let Ok(cache) = ota_cache.lock() {
        // All fresh programs' activators (POTA + SOTA when both are polled).
        let spots: Vec<&propagation::OtaSpot> = cache
            .values()
            .filter(|(stamp, _)| now_unix().saturating_sub(*stamp) <= 600)
            .flat_map(|(_, v)| v.iter())
            .collect();
        if !spots.is_empty() {
            for a in &mut alerts {
                if let Some(sp) = spots
                    .iter()
                    // Base-call match: the spot says K1ABC, the decode may say
                    // K1ABC/P — the suffix is exactly the portable case a park
                    // chaser cares about.
                    .find(|sp| tempo_core::message::same_call(&sp.activator, &a.call))
                {
                    let tag = if sp.program.eq_ignore_ascii_case("SOTA") {
                        propagation::NeedTag::Sota
                    } else {
                        propagation::NeedTag::Pota
                    };
                    if !a.tags.contains(&tag) {
                        a.tags.push(tag);
                        a.headline = format!("{} · {} {}", a.headline, sp.program, sp.reference);
                    }
                }
            }
        }
    }
    // Feed LIVE POTA/SOTA activators onto the board as chase opportunities in their OWN
    // right — not merely as chips on a coincidentally-cluster-spotted station. Most park
    // activators live on the POTA/SOTA networks and never hit the DX cluster, so without
    // this they'd only ever appear in the dedicated hunter panel. Each currently-active
    // activator (fresh poller + recent spot time) that isn't already a row for the same
    // (call, band, mode) is scored via `activation_alert` (any DX award it also satisfies
    // is merged, so a new-entity park outranks a domestic one) and appended.
    const OTA_ACTIVE_SECS: i64 = 3600; // an activation counts as "current" for ~1 h
    if let Ok(cache) = ota_cache.lock() {
        let now = now_unix();
        let fresh: Vec<propagation::OtaSpot> = cache
            .values()
            // Cache STAMP proves the poller is alive; per-spot TIME proves the activation
            // itself is current (SOTA's count-based feed can carry stale rows).
            .filter(|(stamp, _)| now.saturating_sub(*stamp) <= 900)
            .flat_map(|(_, v)| v.iter().cloned())
            .filter(|sp| {
                sp.spot_time_unix
                    .is_none_or(|t| now.saturating_sub(t) <= OTA_ACTIVE_SECS)
            })
            .collect();
        drop(cache);
        for sp in &fresh {
            let Some(alert) = propagation::activation_alert(sp, &needs, &needs.slots()) else {
                continue;
            };
            if alert.call == me_up {
                continue; // never chase yourself
            }
            // Skip if the cluster path already produced this row — the tag loop above has
            // decorated it with the P/S chip + reference.
            if alerts
                .iter()
                .any(|a| a.call == alert.call && a.band == alert.band && a.mode == alert.mode)
            {
                continue;
            }
            alerts.push(alert);
        }
        // Re-sort: an activation that is ALSO a new one must land among the new ones.
        alerts.sort_by(|x, y| y.priority.cmp(&x.priority));
    }
    // Wanted watch list (W1.5): a station on the operator's list must top the
    // board even if it advances no award. This aggregated needs path carries no
    // per-spot CQ status or SNR, so the cq_only/min_snr gates can't be honored
    // here — the operator-facing controls for them are intentionally not shipped
    // (only wanted_calls). We pass is_cq=true / snr=None so every watch-list hit
    // surfaces; `wanted_match`/`wanted_alert` treat unknown SNR as passing.
    if !wanted_calls.is_empty() {
        let wcfg = propagation::WantedConfig {
            calls: &wanted_calls,
            cq_only: false,
            min_snr: None,
        };
        // (a) Decorate existing rows that are on the watch list — loud, on top.
        for a in &mut alerts {
            if !a.tags.contains(&propagation::NeedTag::Wanted)
                && propagation::wanted_match(&a.call, true, None, &wcfg)
            {
                a.tags.insert(0, propagation::NeedTag::Wanted);
                a.priority = a.priority.max(120);
                a.headline = format!("Wanted · {}", a.headline);
            }
        }
        // (b) Surface a loud row for a wanted heard station that produced no
        //     alert (an already-worked entity you still want to catch).
        for h in &heard {
            let up = h.call.to_ascii_uppercase();
            if up == me_up || alerts.iter().any(|a| a.call == up && a.band == h.band) {
                continue;
            }
            if let Some(mut a) = propagation::wanted_alert(
                &h.call,
                &h.band,
                &h.mode,
                h.grid.as_deref(),
                true,
                None,
                &wcfg,
                &needs,
                &needs.slots(),
            ) {
                // wanted_alert doesn't know the spot metadata — carry it over.
                a.freq_mhz = h.freq_mhz;
                a.admitted_at = h.admitted_at;
                a.evidence = h.evidence.clone();
                alerts.push(a);
            }
        }
        alerts.sort_by(|x, y| y.priority.cmp(&x.priority));
    }
    Ok(alerts)
}

/// Import an external ADIF logbook (deduped merge → real "needs"). Takes the
/// file's text; the UI reads the file so no fs/dialog plugin is needed.
#[tauri::command(async)]
fn import_adif(state: State<'_, SharedEngine>, text: String) -> Result<ImportStats, String> {
    let mut eng = engine_lock(&state);
    let (added, skipped, updated, total) = eng.import_adif(&text);
    Ok(ImportStats {
        added,
        skipped,
        updated,
        total,
    })
}

/// Reconcile a confirmation/credit report (LoTW ADIF export) INTO the existing
/// log — upgrades confirmation + credit on already-logged QSOs (which a plain
/// import would skip), rewrites the log file, and returns the diff + any
/// confirmations that matched no logged QSO. Offline; the live LoTW download is a
/// later increment that feeds this the same ADIF.
#[tauri::command]
async fn sync_lotw_report(
    state: State<'_, SharedEngine>,
    text: String,
) -> Result<LotwSyncResult, String> {
    conn_logged(
        "LoTW",
        |r: &LotwSyncResult| {
            format!(
                "file sync OK — {} newly confirmed, {} credited",
                r.newly_confirmed, r.newly_credited
            )
        },
        (|| {
            let mut eng = engine_lock(&state);
            Ok(eng.merge_lotw_report(&text).into())
        })(),
    )
}

// ----- LoTW credential vault + authenticated download -----------------------
// The LoTW *website* password lives in the OS keychain (Windows Credential
// Manager / macOS Keychain / Linux Secret Service), never in settings.json or a
// log. The username + the incremental high-water cursor are non-secret and live
// in Settings.

const LOTW_KEYCHAIN_SERVICE: &str = "tempo";
const LOTW_KEYCHAIN_USER: &str = "lotw-password";
const EQSL_KEYCHAIN_USER: &str = "eqsl-password";
const QRZ_KEYCHAIN_USER: &str = "qrz-password";
const QRZ_LOGBOOK_KEYCHAIN_USER: &str = "qrz-logbook-key";
const HAMQTH_KEYCHAIN_USER: &str = "hamqth-password";
const CLUBLOG_KEYCHAIN_USER: &str = "clublog-password";
const HRDLOG_KEYCHAIN_USER: &str = "hrdlog-code";
const CLOUDLOG_KEYCHAIN_USER: &str = "cloudlog-key";

/// Client name Nexus sends to HRDLog.net's `NewEntry.aspx` as `App` (aids their
/// support / usage stats). Non-secret.
const HRDLOG_APP_NAME: &str = "Nexus";

/// Session-level kill-switch for ClubLog auto-push: set on a 403 (bad creds) so we
/// stop re-POSTing every QSO (ClubLog IP-blocks repeated auth failures); reset when
/// the operator changes a ClubLog credential.
static CLUBLOG_SUSPENDED: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);
/// Announce-once latch for the "no ClubLog credentials" pause — reset when credentials
/// become ready so the notice re-arms for the next dry spell (F4MQS storm fix).
static CLUBLOG_NO_CREDS_ANNOUNCED: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Session kill-switch for the AUTOMATIC LoTW batch upload: set on a rejected or
/// auth-failed batch so the timer stops offering it. This is the whole reason the
/// automatic upload was allowed to exist.
///
/// `UploadOutcome::is_sent()` deliberately excludes `Rejected` and `AuthFail`, so
/// `lotw_unsent_indices()` keeps handing back a batch that already failed. Without this
/// latch a missing Callsign Certificate — or ONE malformed QSO, since TQSL's exit 9
/// stamps the entire batch `Rejected` without naming the record it dropped — would
/// re-sign and re-upload everything every interval, spawning TQSL each time. That is the
/// ClubLog storm class ([`CLUBLOG_SUSPENDED`]) with a GUI-linked binary in place of an
/// HTTP POST. One failure, one notice, and it waits for the operator; a save that touches
/// any LoTW upload setting re-arms it (see `save_settings`). A network failure ("retry")
/// deliberately does NOT latch — nothing is wrong with the operator's setup.
static LOTW_AUTO_SUSPENDED: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);
/// Announce-once latch for the pause above, so a suspended connector costs exactly one
/// line in the connection log rather than one per tick.
static LOTW_AUTO_ANNOUNCED: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Are ALL the ClubLog credentials present (email + API key + app-password)? A missing one
/// is an operator-fixable Settings gap, not a transient network failure — the worker skips
/// the leg session-wide rather than retrying it per QSO. `email`/`key` come from the
/// settings snapshot the caller already holds; only the keychain read is done here.
fn clublog_credentials_ready(email: &str, effective_key: &str) -> bool {
    !email.trim().is_empty()
        && !effective_key.is_empty()
        && clublog_keychain()
            .map(|e| e.get_password().is_ok())
            .unwrap_or(false)
}

/// One connectivity event for the Settings ▸ Connections log — the answer to
/// "I hit save / it synced / it failed and I couldn't tell". Every connector
/// action (credential save, login, download, push, feed start/stop, rejection)
/// records one of these; the UI shows the rolling tail.
#[derive(Clone, serde::Serialize)]
#[serde(rename_all = "camelCase")]
struct ConnEvent {
    ts_unix: i64,
    connector: String,
    /// "ok" | "info" | "error"
    level: String,
    message: String,
}

static CONN_LOG: Mutex<std::collections::VecDeque<ConnEvent>> =
    Mutex::new(std::collections::VecDeque::new());
const CONN_LOG_CAP: usize = 200;

/// Last real ROUND-TRIP outcome for the two connectors that leave no per-QSO stamp
/// (HRDLog.net, Cloudlog). `(id, last_success, last_failure(when, detail))`.
///
/// BOTH halves are kept, and separately: one slot per connector would mean a failure
/// erases the prior success and a recovery erases the failure, so "worked until 3pm,
/// failing since" — the single most useful thing this panel can say — would be
/// unrepresentable. `note_conn_health` therefore upserts into the matching half only and
/// never touches the other.
///
/// Session-only, and honestly so: the other four connectors read their history out of
/// `log.adi` and survive a restart, these two show "not verified yet" until the next QSO.
/// Deliberately NOT derived from [`CONN_LOG`] — that log's "ok" level also covers
/// credential SAVES, and counting a save as a working upload is the same green-forever
/// lie in a new costume.
///
/// `Vec::new()` is const (a `HashMap` would not be), and n ≤ 2, so a linear scan is right.
#[allow(clippy::type_complexity)]
static CONN_HEALTH: Mutex<Vec<(&'static str, Option<i64>, Option<(i64, String)>)>> =
    Mutex::new(Vec::new());

/// Record a real round trip for a session-only connector. `ok` picks the half; the other
/// half is left exactly as it was.
fn note_conn_health(id: &'static str, ok: bool, detail: String) {
    let now = now_unix();
    // Poisoned-lock recovery, the conn_log pattern: a panicked command holding this must
    // not silently freeze the health panel for the rest of the session.
    let mut m = CONN_HEALTH.lock().unwrap_or_else(|e| e.into_inner());
    let slot = match m.iter_mut().find(|(k, _, _)| *k == id) {
        Some(s) => s,
        None => {
            m.push((id, None, None));
            m.last_mut().expect("just pushed")
        }
    };
    if ok {
        slot.1 = Some(now);
    } else {
        slot.2 = Some((now, detail));
    }
}

/// Read one connector's session health back as `(last_success, last_failure_when,
/// last_failure_detail)`.
fn conn_health_of(id: &str) -> (Option<i64>, Option<i64>, Option<String>) {
    let m = CONN_HEALTH.lock().unwrap_or_else(|e| e.into_inner());
    match m.iter().find(|(k, _, _)| *k == id) {
        Some((_, ok, fail)) => (
            *ok,
            fail.as_ref().map(|(w, _)| *w),
            fail.as_ref().map(|(_, d)| d.clone()),
        ),
        None => (None, None, None),
    }
}

/// Record a connectivity event (and mirror it to stderr for dev logs).
fn conn_log(connector: &str, level: &str, message: impl Into<String>) {
    let message = message.into();
    eprintln!("conn[{connector}/{level}]: {message}");
    let mut log = CONN_LOG.lock().unwrap_or_else(|e| e.into_inner());
    log.push_back(ConnEvent {
        ts_unix: now_unix() as i64,
        connector: connector.to_string(),
        level: level.to_string(),
        message,
    });
    while log.len() > CONN_LOG_CAP {
        log.pop_front();
    }
}

/// Wrap a connector operation result into the connection log: success and
/// failure BOTH become visible events (the operator could previously tell
/// neither). Returns the result unchanged.
fn conn_logged<T>(
    connector: &str,
    ok_msg: impl FnOnce(&T) -> String,
    r: Result<T, String>,
) -> Result<T, String> {
    match &r {
        Ok(v) => conn_log(connector, "ok", ok_msg(v)),
        Err(e) => conn_log(connector, "error", e.clone()),
    }
    r
}

/// The rolling connectivity log, newest first.
#[tauri::command]
fn get_connection_log() -> Vec<ConnEvent> {
    let log = CONN_LOG.lock().unwrap_or_else(|e| e.into_inner());
    log.iter().rev().cloned().collect()
}

/// Per-connector STATUS: whether a credential is stored, and — the part that matters —
/// what happened the last time Nexus actually talked to the service.
///
/// This used to carry `stored` alone, and the panel painted its dot from it. That answered
/// the wrong question: a revoked ClubLog app-password, a rotated QRZ Logbook key or a
/// mistyped HRDLog upload code all stayed green forever, because the secret was still
/// sitting in the keychain. `stored` is kept — it is still the right answer for "you never
/// entered this" — but the dot now comes from the timestamps below.
///
/// The UI derives the displayed state from these fields (see `ui/src/settings/connHealth.ts`),
/// deliberately rather than shipping a status string: two timestamps cannot drift out of
/// step with a Rust enum, and the derivation is unit-testable on the TS side.
/// Never returns the secrets themselves.
#[derive(serde::Serialize)]
#[serde(rename_all = "camelCase")]
struct CredStatus {
    /// Stable slug — "lotw" | "qrz-xml" | "qrz-logbook" | "eqsl" | "clublog" | "hrdlog" |
    /// "cloudlog" | "repeaterbook". The UI used to branch on the PROSE label
    /// (`connector === 'QRZ Logbook'`), which breaks the day someone rewords a legend.
    id: String,
    /// Display label.
    connector: String,
    /// A secret exists in the OS keychain (or key field) for this connector.
    stored: bool,
    /// The associated non-secret identity (username/email), for display.
    identity: String,
    /// Does this connector push QSOs outward at all? False for the lookup-only ones (QRZ
    /// callbook, RepeaterBook), where "never uploaded anything" is not a fault and must
    /// not be rendered as one.
    uploads: bool,
    /// Is its auto-upload switched on? Separates "nothing has happened because you turned
    /// it off" from "nothing has happened and that is a problem".
    enabled: bool,
    /// Newest upload this connector actually accepted. `None` = never verified, which the
    /// UI must render as amber "not verified yet" and NEVER as green. Named
    /// `last_success_unix` rather than `last_ok_unix` on purpose: `lastOkUnix` invites a
    /// hand-written `lastOKUnix` on the TS side, the silent `decodeFLowHz` failure.
    last_success_unix: Option<i64>,
    /// Newest failure. Compared against `last_success_unix` in the UI to decide
    /// failing-vs-working.
    last_failure_unix: Option<i64>,
    /// The service's own (already sanitized) reason for that failure.
    last_failure_detail: Option<String>,
    /// Session kill-switch tripped (ClubLog's 403 latch). While set, EVERY ClubLog leg is
    /// skipped — today that appears only as one line in a 200-entry log the operator has
    /// almost certainly scrolled past.
    paused: bool,
}

#[tauri::command(async)]
fn get_credentials_status(state: State<'_, SharedEngine>) -> Result<Vec<CredStatus>, String> {
    // ONE lock, taken once and released before the eight keychain reads below (keychain
    // I/O is the slow part, and the radio thread contends for this lock). `upload_health`
    // is O(records) but only cheap Option comparisons, and it BORROWS — never `get_log`,
    // which clones the whole record vector and would be a real regression on a big log at
    // the panel's 5 s poll.
    #[allow(clippy::type_complexity)]
    let (
        lotw_user,
        eqsl_user,
        qrz_user,
        clublog_email,
        mycall,
        clublog_key,
        cloudlog_url,
        health,
        toggles,
    ) = {
        let eng = engine_lock(&state);
        let health = eng.upload_health();
        let st = eng.settings();
        (
            st.lotw_username.clone(),
            st.eqsl_username.clone(),
            st.qrz_username.clone(),
            st.clublog_email.clone(),
            st.mycall.clone(),
            // The API key is an APPLICATION (developer) credential, not a user
            // one: a Settings override OR the key baked into official installer
            // builds (CLUBLOG_API_KEY at build time) both satisfy it. The user's
            // own credentials are only email + app-password.
            !effective_clublog_key(&st.clublog_api_key).is_empty(),
            st.cloudlog_url.clone(),
            health,
            // (qrz-logbook, clublog, eqsl, hrdlog, cloudlog) auto-upload switches. Cloudlog
            // mirrors the worker's own gate — a URL-less Cloudlog is off however the toggle
            // reads (see the auto-upload worker).
            (
                st.qrz_logbook_upload,
                st.clublog_upload,
                st.eqsl_upload,
                st.hrdlog_upload,
                st.cloudlog_upload && !st.cloudlog_url.trim().is_empty(),
            )
        )
    };
    let (qrz_book_on, clublog_on, eqsl_on, hrdlog_on, cloudlog_on) = toggles;
    let (hrdlog_ok, hrdlog_fail, hrdlog_detail) = conn_health_of("hrdlog");
    let (cloudlog_ok, cloudlog_fail, cloudlog_detail) = conn_health_of("cloudlog");
    let has = |entry: Result<keyring::Entry, String>| {
        entry
            .and_then(|e| e.get_password().map_err(|er| er.to_string()))
            .is_ok()
    };
    // LoTW, QRZ Logbook, eQSL and ClubLog read their history off the persisted per-QSO
    // stamps, so it survives a restart. The lookup-only rows (QRZ callbook, RepeaterBook)
    // carry `uploads: false` and no history at all — see the note on `uploads`.
    let stored_lotw = has(lotw_keychain());
    let stored_qrz = has(qrz_keychain());
    let stored_rb = has(repeaterbook_keychain());
    Ok(vec![
        CredStatus {
            id: "lotw".into(),
            connector: "LoTW".into(),
            stored: stored_lotw,
            identity: lotw_user,
            uploads: true,
            // LoTW's upload has no per-QSO auto toggle of its own beyond the batch timer,
            // and the manual Logbook button is always available — so "enabled" here means
            // "configured", not "on a timer".
            enabled: stored_lotw,
            last_success_unix: health.lotw.last_success_unix,
            last_failure_unix: health.lotw.last_failure_unix,
            last_failure_detail: health.lotw.last_failure_detail,
            paused: false,
        },
        CredStatus {
            id: "qrz-xml".into(),
            connector: "QRZ callbook (name/QTH)".into(),
            stored: stored_qrz,
            identity: qrz_user.clone(),
            // Lookup only. The signal genuinely exists (lookups run constantly while
            // operating) but is not wired to this panel — an expired XML subscription
            // still reads as a benign grey row. Flagged rather than pretended away.
            uploads: false,
            enabled: stored_qrz,
            last_success_unix: None,
            last_failure_unix: None,
            last_failure_detail: None,
            paused: false,
        },
        CredStatus {
            id: "qrz-logbook".into(),
            connector: "QRZ Logbook".into(),
            stored: has(qrz_logbook_keychain()),
            identity: qrz_user,
            uploads: true,
            enabled: qrz_book_on,
            last_success_unix: health.qrz.last_success_unix,
            last_failure_unix: health.qrz.last_failure_unix,
            last_failure_detail: health.qrz.last_failure_detail,
            paused: false,
        },
        CredStatus {
            id: "eqsl".into(),
            connector: "eQSL".into(),
            stored: has(eqsl_keychain()),
            identity: eqsl_user,
            uploads: true,
            enabled: eqsl_on,
            last_success_unix: health.eqsl.last_success_unix,
            last_failure_unix: health.eqsl.last_failure_unix,
            last_failure_detail: health.eqsl.last_failure_detail,
            paused: false,
        },
        CredStatus {
            id: "clublog".into(),
            connector: "ClubLog".into(),
            stored: has(clublog_keychain()) && clublog_key,
            identity: clublog_email,
            uploads: true,
            enabled: clublog_on,
            last_success_unix: health.clublog.last_success_unix,
            last_failure_unix: health.clublog.last_failure_unix,
            last_failure_detail: health.clublog.last_failure_detail,
            // The 403 latch, finally visible. Note it is process-global: two instances
            // sharing one log will disagree until the log-derived AuthFail stamp reaches
            // the other one, which then shows `failing` rather than `paused`.
            paused: CLUBLOG_SUSPENDED.load(std::sync::atomic::Ordering::Relaxed),
        },
        CredStatus {
            // The station callsign IS the HRDLog identity (the upload code is the
            // only secret); show mycall so a save is visibly attributed.
            id: "hrdlog".into(),
            connector: "HRDLog.net".into(),
            stored: has(hrdlog_keychain()),
            identity: mycall,
            uploads: true,
            enabled: hrdlog_on,
            // Session-only: HRDLog leaves no per-QSO stamp, so after a restart this reads
            // "not verified yet" until the next QSO. Honest, and not green.
            last_success_unix: hrdlog_ok,
            last_failure_unix: hrdlog_fail,
            last_failure_detail: hrdlog_detail,
            paused: false,
        },
        CredStatus {
            id: "cloudlog".into(),
            connector: "Cloudlog".into(),
            stored: has(cloudlog_keychain()),
            identity: cloudlog_url,
            uploads: true,
            enabled: cloudlog_on,
            // Session-only, same as HRDLog above.
            last_success_unix: cloudlog_ok,
            last_failure_unix: cloudlog_fail,
            last_failure_detail: cloudlog_detail,
            paused: false,
        },
        CredStatus {
            // The token is app-scoped (an rbuapp_… token the user generates on
            // RepeaterBook); there's no separate username identity to show.
            id: "repeaterbook".into(),
            connector: "RepeaterBook".into(),
            stored: stored_rb,
            identity: String::new(),
            uploads: false,
            enabled: stored_rb,
            last_success_unix: None,
            last_failure_unix: None,
            last_failure_detail: None,
            paused: false,
        },
    ])
}

/// The effective ClubLog **application** key: the Settings override when set,
/// else the key baked into official installer builds at compile time
/// (`CLUBLOG_API_KEY`, see build.rs). Empty = this build has no key (source
/// build without the env var) and ClubLog features that need one are off.
fn effective_clublog_key(settings_key: &str) -> String {
    let k = settings_key.trim();
    if !k.is_empty() {
        return k.to_string();
    }
    option_env!("CLUBLOG_API_KEY")
        .unwrap_or("")
        .trim()
        .to_string()
}

fn lotw_keychain() -> Result<keyring::Entry, String> {
    keyring::Entry::new(LOTW_KEYCHAIN_SERVICE, LOTW_KEYCHAIN_USER)
        .map_err(|e| format!("couldn't open the system keychain: {e}"))
}

